export const enums = {"wiki":[{"id":"SSH.T1007","stixId":"attack-pattern--5411a228-5557-458d-b417-4ef8ed0dcdc3","name":"System Service Discovery","description":"Adversaries may try to gather information about registered local system services. Adversaries may obtain information about services using tools as well as OS utility commands.\nAdversaries may use the information from System Service Discovery during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1007","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1007 System Service Discovery","platforms":["Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0007","name":"Discovery","shortname":"discovery"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1007","url":"https://spaceshield.esa.int/techniques/T1007"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1070","stixId":"attack-pattern--0c34c54a-982a-4744-8f78-8b390d499a0a","name":"Indicator Removal on Host","description":"Adversaries may delete or modify artifacts generated on a host system to remove evidence of their presence or hinder defenses. Various artifacts may be created by an adversary or something that can be attributed to an adversary's actions. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1070","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1070 Indicator Removal on Host","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2066","stixId":"course-of-action--f8b0b1ea-b1eb-404e-8d57-428eb81c5a2b","name":"Log integrity protection","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2066"}],"externalReferences":[{"source":"mitre-attack","id":"T1070","url":"https://spaceshield.esa.int/techniques/T1070"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1070.001","stixId":"attack-pattern--dc37997e-4824-47a3-8ab2-8973ade2714c","name":"Clear Log/Command History","description":"If a log is available, an attacker can delete logging onboard the spacecraft to hide illegitimate operations (a TC log service is usually not implemented). (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1070/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1070.001 Clear Log/Command History","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[{"id":"SSH.T1070","stixId":"attack-pattern--0c34c54a-982a-4744-8f78-8b390d499a0a","name":"Indicator Removal on Host","description":"Adversaries may delete or modify artifacts generated on a host system to remove evidence of their presence or hinder defenses. Various artifacts may be created by an adversary or something that can be attributed to an adversary's actions. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1070"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1070.001","url":"https://spaceshield.esa.int/techniques/T1070/001"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1106","stixId":"attack-pattern--189b0ace-4ecc-4354-a2dc-b41da15f6640","name":"Native API","description":"Operating systems like RTEMS provide API to interact with. An attacker can exploit them or abuse a vulnerability/misconfiguration to maliciously execute code or commands. (Citation: MITRE ATT&CK)\n\nStandard/references: (Citation: SRC028)","url":"https://spaceshield.esa.int/techniques/T1106","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1106 Native API","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0002","name":"Execution","shortname":"execution"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1106","url":"https://spaceshield.esa.int/techniques/T1106"},{"source":"SRC028","url":"https://docs.rtems.org/branches/master/c-user/index.html"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1195","stixId":"attack-pattern--952ef0d4-f55c-4124-8715-572c11fc10b9","name":"Supply Chain Compromise","description":"Adversaries may manipulate products or product delivery mechanisms prior to receipt by a final consumer for the purpose of data or system compromise. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1195","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1195 Supply Chain Compromise","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2047","stixId":"course-of-action--3c4d0502-63a4-4368-8e98-93f989c3181e","name":"Vulnerability/malware scanning","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2047"},{"id":"SSH.M2050","stixId":"course-of-action--001c3469-f0f2-422a-823b-77fee2cfa91c","name":"Supply from trustworthy sources only","description":"Source components from certified, verified suppliers to mitigate risks of counterfeit or tampered hardware/software.","url":"https://attack.mitre.org/mitigations/M2050"},{"id":"SSH.M2019","stixId":"course-of-action--14df2304-0f7c-43d8-8b4a-41d1747a2123","name":"Data integrity schemes","description":"Use data integrity schemes to protect data from unauthorized modifications, or from unintentional corruptions due to noise or storage defects (hashing, check values, digital signatures). SDLS provides integrity protection on the transmitted data, with the computation of a MAC. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2019"},{"id":"SSH.M2048","stixId":"course-of-action--f61a918d-b3b7-432e-a2cb-4393a660de0d","name":"Digital signing of software components","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2048"},{"id":"SSH.M1046","stixId":"course-of-action--40f3b623-2abd-4311-a016-8b1a2aff979d","name":"Boot Integrity","description":"Use secure methods to boot a system and verify the integrity of the operating system and loading mechanisms. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1046"},{"id":"SSH.M2049","stixId":"course-of-action--4ca150b7-c025-48ab-9a59-ef9fe8369e36","name":"Defense-in-depth measures","description":"Implement multiple layers of protection, considering encryption, authentication, on-board isolation mechanisms, and anomaly detection, restricting the impact of an intrusion and enhancing the resilience of the spacecraft.","url":"https://spaceshield.esa.int/mitigations/M2049"}],"externalReferences":[{"source":"mitre-attack","id":"T1195","url":"https://spaceshield.esa.int/techniques/T1195"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1195.001","stixId":"attack-pattern--5d84c1e5-5917-439c-bcf5-216abe908463","name":"Compromise Software Dependencies and Development Tools","description":"Adversaries may manipulate software dependencies and development tools prior to receipt by a final consumer for the purpose of data or system compromise. Applications often depend on external software to function properly. Popular open source projects that are used as dependencies in many applications may be targeted as a means to add malicious code to users of the dependency.\nTargeting may be specific to a desired victim set or may be distributed to a broad set of consumers but only move on to additional tactics on specific victims. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1195/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1195.001 Compromise Software Dependencies and Development Tools","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T1195","stixId":"attack-pattern--952ef0d4-f55c-4124-8715-572c11fc10b9","name":"Supply Chain Compromise","description":"Adversaries may manipulate products or product delivery mechanisms prior to receipt by a final consumer for the purpose of data or system compromise. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1195"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1195.001","url":"https://spaceshield.esa.int/techniques/T1195/001"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1195.002","stixId":"attack-pattern--e80c1d84-8bb0-4136-86db-7d7ca493df23","name":"Compromise Software Supply Chain","description":"Adversaries may manipulate application software prior to receipt by a final consumer for the purpose of data or system compromise. Supply chain compromise of software can take place in a number of ways, including manipulation of the application source code, manipulation of the update/distribution mechanism for that software, or replacing compiled releases with a modified version.\nTargeting may be specific to a desired victim set or may be distributed to a broad set of consumers but only move on to additional tactics on specific victims. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1195/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1195.002 Compromise Software Supply Chain","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T1195","stixId":"attack-pattern--952ef0d4-f55c-4124-8715-572c11fc10b9","name":"Supply Chain Compromise","description":"Adversaries may manipulate products or product delivery mechanisms prior to receipt by a final consumer for the purpose of data or system compromise. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1195"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1195.002","url":"https://spaceshield.esa.int/techniques/T1195/002"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1195.003","stixId":"attack-pattern--689ac63e-bfc3-40be-aeef-842602147032","name":"Compromise Hardware Supply Chain","description":"An attacker can replace an hardware component in the supply chain with a custom or counterfeit part, to damage the system or to use it as a future backdoor. An attacker can also induce the intentional use of a not genuine HW component to reduce the system reliability. (Citation: SRC017)","url":"https://spaceshield.esa.int/techniques/T1195/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1195.003 Compromise Hardware Supply Chain","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T1195","stixId":"attack-pattern--952ef0d4-f55c-4124-8715-572c11fc10b9","name":"Supply Chain Compromise","description":"Adversaries may manipulate products or product delivery mechanisms prior to receipt by a final consumer for the purpose of data or system compromise. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1195"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1195.003","url":"https://spaceshield.esa.int/techniques/T1195/003"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T1489","stixId":"attack-pattern--22e3cc99-f2b6-47de-a719-d5b84b5499fd","name":"Service Stop","description":"An attacker can interrupt services, disabling them or taking control over them. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1489","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1489 Service Stop","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1489","url":"https://spaceshield.esa.int/techniques/T1489"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1489.001","stixId":"attack-pattern--f01fcc7f-bf3c-4f52-ade8-a1f9d07c1f4f","name":"Ground system loss","description":"The ground facility can be disabled, or an attacker can take control of it, via cyber or physical attack. The loss of the GS can be also caused by environmental factors, uncontrolled or induced (e.g, fire). (Citation: SRC017)","url":"https://spaceshield.esa.int/techniques/T1489/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1489.001 Ground system loss","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T1489","stixId":"attack-pattern--22e3cc99-f2b6-47de-a719-d5b84b5499fd","name":"Service Stop","description":"An attacker can interrupt services, disabling them or taking control over them. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1489"}],"mitigations":[{"id":"SSH.M2022","stixId":"course-of-action--f7cc4284-b53a-4ed2-a18d-e280f1e4b464","name":"Access control","description":"Access control systems authenticate users and enforce authorization, avoiding that attackers or unauthorized users reach unpermitted services and resources, modify system configurations, and take control of them.\t\nAccess control is needed to identify actors who try to interact with the system, or take place in a network, and it defines if they are authorized or not. \t\nThe installation of backdoors in the system, and the exfiltration of data from it can be prevented or at least made more difficult if an access control is implemented. Furthermore, it can protect from alteration of system settings, disablement of defenses, or from the deletion of logs.\nWithout the access control, the attacker could take control of the asset, abusing the resources, misconfiguring OBCP to hijack or damage it, he can interrupt the provided services or also take possession of the spacecraft, changing the cryptographic keys. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2022"},{"id":"SSH.M2020","stixId":"course-of-action--f6bfbfaa-ebaa-4cf2-a576-271c2486a93d","name":"Resilience","description":"Resilient hardware (e.g., SOS) protects systems, facilities, services, or data from damage or from Service interruption attacks. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2020"},{"id":"SSH.M2009","stixId":"course-of-action--1bf18421-76b5-4cf4-8b44-db2bcc776ae9","name":"Redundancy","description":"Redundancy can improve the reliability and availability of a system, a data source, a service or a resource from faults and interruptions, either accidental or produced, or from deceiving attempts.\t\nIt consists in the inclusion of extra components, either hardware or software, which are not strictly necessary to functioning, but that start to operate in case of failure in other components.\nAs a downside, it increases the cost and complexity of a system design. (Citation: SRC017) (Citation: SRC032) (Citation: SRC033) ","url":"https://spaceshield.esa.int/mitigations/M2009"},{"id":"SSH.M2021","stixId":"course-of-action--a6067c0c-6f5a-49c6-b5d8-d95487543a26","name":"Physical security","description":"Guards, gates, and other physical security countermeasures, permit to defend facilities from undesirable accesses, sabotages, or damages made on purpose. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2021"},{"id":"SSH.M2010","stixId":"course-of-action--fd9cec93-01ce-46bb-a135-f233db751cbd","name":"Diversity","description":"Diversity can protect a data source from faults or deceiving attempts. Different components or software are less likely to brake or have the same vulnerabilities, and a compromise of one of them doesn't automatically become a compromise of the whole system. Different locations are exposed to different physical problems. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2010"}],"externalReferences":[{"source":"mitre-attack","id":"T1489.001","url":"https://spaceshield.esa.int/techniques/T1489/001"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T1489.002","stixId":"attack-pattern--936b16ca-786b-4ef6-a31a-3bbfdaa219f2","name":"Disabling Payload Service","description":"An attacker can disable the payload, or parts of it, leveraging TC switch on-off commands. In a mission with a direct link for the payload, the latter can be disabled compromising its command channel. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1489/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1489.002 Disabling Payload Service","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T1489","stixId":"attack-pattern--22e3cc99-f2b6-47de-a719-d5b84b5499fd","name":"Service Stop","description":"An attacker can interrupt services, disabling them or taking control over them. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1489"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1489.002","url":"https://spaceshield.esa.int/techniques/T1489/002"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T1496","stixId":"attack-pattern--d1b50ae2-59f1-42bb-9e06-5597cfdc7876","name":"Resource Hijacking","description":"An attacker can hijack resources of the space vehicle using them for different purposes.","url":"https://spaceshield.esa.int/techniques/T1496","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1496 Resource Hijacking","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2002","stixId":"course-of-action--f340a10b-0cc2-4ade-bf9c-5eff01877b3a","name":"Authentication","description":"Authentication permits a secure access to the resource, verifying the actor's identity. It also protects a command or a message from spoofing or modifications. CCSDS SDLS protocol incorporates authentication through MAC. Authentication protects from attacks aiming to access unauthorized resources, to spoof legitimate users, or to manipulate data and communications. (Citation: SRC008) (Citation: SRC017) (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2002"}],"externalReferences":[{"source":"mitre-attack","id":"T1496","url":"https://spaceshield.esa.int/techniques/T1496"}]},{"id":"SSH.T1542","stixId":"attack-pattern--8de0a0ae-e883-434e-94c9-03bfa0598ec9","name":"Pre-OS Boot","description":"\"Adversaries may abuse Pre-OS Boot mechanisms as a way to establish persistence on a system.\" Adversaries can obtain it modifying or replacing components before the launch or updating them later if an update capability is implemented. Detection is very difficult, because defenses are usually working at higher levels.\n\nPersistence at a pre-OS level can be gained modifying the firmware in a resource.\nSystem firmware is quite static, and it doesn't usually provide detection capabilities. A firmware level manipulation can remain unnoticed until next phases of the attack.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1542","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1542 Pre-OS Boot","platforms":["Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M1046","stixId":"course-of-action--40f3b623-2abd-4311-a016-8b1a2aff979d","name":"Boot Integrity","description":"Use secure methods to boot a system and verify the integrity of the operating system and loading mechanisms. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1046"}],"externalReferences":[{"source":"mitre-attack","id":"T1542","url":"https://spaceshield.esa.int/techniques/T1542"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T1542.001","stixId":"attack-pattern--34b01204-44f3-49f3-9d17-5b3ada339658","name":"System Firmware Exploitation","description":"Persistence at a pre-OS level can be gained modifying the firmware in a resource.\nSystem firmware is quite static, and it doesn't usually provide detections capabilities. A firmware level manipulation can remain unnoticed until next phases of the attack. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1542/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1542.001 System Firmware Exploitation","platforms":["None"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T1542","stixId":"attack-pattern--8de0a0ae-e883-434e-94c9-03bfa0598ec9","name":"Pre-OS Boot","description":"\"Adversaries may abuse Pre-OS Boot mechanisms as a way to establish persistence on a system.\" Adversaries can obtain it modifying or replacing components before the launch or updating them later if an update capability is implemented. Detection is very difficult, because defenses are usually working at higher levels.\n\nPersistence at a pre-OS level can be gained modifying the firmware in a resource.\nSystem firmware is quite static, and it doesn't usually provide detection capabilities. A firmware level manipulation can remain unnoticed until next phases of the attack.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1542"}],"mitigations":[{"id":"SSH.M1046","stixId":"course-of-action--40f3b623-2abd-4311-a016-8b1a2aff979d","name":"Boot Integrity","description":"Use secure methods to boot a system and verify the integrity of the operating system and loading mechanisms. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1046"}],"externalReferences":[{"source":"mitre-attack","id":"T1542.001","url":"https://spaceshield.esa.int/techniques/T1542/001"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1557","stixId":"attack-pattern--c0b540cb-fa4e-4412-9d48-579591d33092","name":"Adversary in the Middle","description":"Adversaries may attempt to position themselves between two or more networked devices using an adversary-in-the-middle (AiTM) technique.(Citation: MITRE ATT&CK)\n\nIf unauthenticated gateways or unauthenticated interplanetary nodes are used, an adversary can substitute them with an own resource to collect or modify transmitted data.\nA satellite with stolen credential can take place into a dynamic constellation and collect data.\n","url":"https://spaceshield.esa.int/techniques/T1557","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1557 Adversary in the Middle","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2067","stixId":"course-of-action--fac12398-47a2-4829-afa7-3d1f22a531bf","name":"Authentication combined with means to ensure the identity of the other party using certificates or pre-shared keys","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2067"}],"externalReferences":[{"source":"mitre-attack","id":"T1557","url":"https://spaceshield.esa.int/techniques/T1557"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1557.001","stixId":"attack-pattern--78f47797-e47b-4478-a5c8-e6cc7e923c6b","name":"Unauthenticated gateway or unauthenticated interplanetary node","description":"If unauthenticated gateways or unauthenticated interplanetary nodes are used, an adversary can substitute them with an own resource, to collect or modify transmitted data. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1557/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1557.001 Unauthenticated gateway or unauthenticated interplanetary node","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[{"id":"SSH.T1557","stixId":"attack-pattern--c0b540cb-fa4e-4412-9d48-579591d33092","name":"Adversary in the Middle","description":"Adversaries may attempt to position themselves between two or more networked devices using an adversary-in-the-middle (AiTM) technique.(Citation: MITRE ATT&CK)\n\nIf unauthenticated gateways or unauthenticated interplanetary nodes are used, an adversary can substitute them with an own resource to collect or modify transmitted data.\nA satellite with stolen credential can take place into a dynamic constellation and collect data.\n","url":"https://spaceshield.esa.int/techniques/T1557"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1557.001","url":"https://spaceshield.esa.int/techniques/T1557/001"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T1557.002","stixId":"attack-pattern--fb519858-01f0-44a6-92ac-78aa765b9372","name":"Satellite constellation","description":"A satellite with stolen credential can take place into a dynamic constellation and collect data. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1557/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1557.002 Satellite constellation","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[{"id":"SSH.T1557","stixId":"attack-pattern--c0b540cb-fa4e-4412-9d48-579591d33092","name":"Adversary in the Middle","description":"Adversaries may attempt to position themselves between two or more networked devices using an adversary-in-the-middle (AiTM) technique.(Citation: MITRE ATT&CK)\n\nIf unauthenticated gateways or unauthenticated interplanetary nodes are used, an adversary can substitute them with an own resource to collect or modify transmitted data.\nA satellite with stolen credential can take place into a dynamic constellation and collect data.\n","url":"https://spaceshield.esa.int/techniques/T1557"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1557.002","url":"https://spaceshield.esa.int/techniques/T1557/002"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T1562","stixId":"attack-pattern--b493fb61-bf68-4121-8708-93206d2d3e63","name":"Impair Defenses","description":"Adversaries may maliciously modify components of a victim environment in order to hinder or disable defensive mechanisms. This involves impairing preventative defenses and detection capabilities that defenders can use to audit activity and identify malicious behavior. (Citation: MITRE ATT&CK) (Citation: SRC008)","url":"https://spaceshield.esa.int/techniques/T1562","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1562 Impair Defenses","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2065","stixId":"course-of-action--c75e9af7-4973-4a93-bdcc-fbf703f893c7","name":"Separate authentication for critical commands","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2065"},{"id":"SSH.M2053","stixId":"course-of-action--8a215305-a16e-43de-a150-8f6bc65e8a44","name":"Role Based Access Control","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2053"}],"externalReferences":[{"source":"mitre-attack","id":"T1562","url":"https://spaceshield.esa.int/techniques/T1562"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1562.001","stixId":"attack-pattern--94486cdd-302d-49ab-913b-55240182cc62","name":"Triggering the clear mode","description":"An attacker can trigger the clear mode accessing TC or consuming its resources, , to disable or limit the security level of the spacecraft. If a 'clear mode' is implemented, the conditions under which, and by which, it is activated should be carefully analyzed, as those might introduce major security vulnerabilities. (Citation: SRC008) (Citation: SRC012)\n\nStandard/references: (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T1562/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1562.001 Triggering the clear mode","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[{"id":"SSH.T1562","stixId":"attack-pattern--b493fb61-bf68-4121-8708-93206d2d3e63","name":"Impair Defenses","description":"Adversaries may maliciously modify components of a victim environment in order to hinder or disable defensive mechanisms. This involves impairing preventative defenses and detection capabilities that defenders can use to audit activity and identify malicious behavior. (Citation: MITRE ATT&CK) (Citation: SRC008)","url":"https://spaceshield.esa.int/techniques/T1562"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1562.001","url":"https://spaceshield.esa.int/techniques/T1562/001"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T1583","stixId":"attack-pattern--b36d226e-497b-4c01-99d1-cf684cc96772","name":"Acquire or Build Infrastructure","description":"An attacker can acquire a Ground Segment, a Ground Station service (e.g. Amazon service ), satellite(s), or other infrastructure that can be useful to his attacking plans. Such an infrastructure can be a set of antennas, lasers, Software Defined Radios (SDR) or other equipment able to transmit the desired signals. Such equipment can be fixed on ground, mounted on vehicles like trucks, ships, aircraft, or also installed on board of satellites.","url":"https://spaceshield.esa.int/techniques/T1583","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1583 Acquire or Build Infrastructure","platforms":["Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1583","url":"https://spaceshield.esa.int/techniques/T1583"}]},{"id":"SSH.T1583.001","stixId":"attack-pattern--91bb0e95-8b2d-40a8-b341-ed82ae7a3def","name":"Acquire Ground-station/ Ground segment","description":"Build a new ground station or gaining control of an existing one.","url":"https://spaceshield.esa.int/techniques/T1583/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1583.001 Acquire Ground-station/ Ground segment","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T1583","stixId":"attack-pattern--b36d226e-497b-4c01-99d1-cf684cc96772","name":"Acquire or Build Infrastructure","description":"An attacker can acquire a Ground Segment, a Ground Station service (e.g. Amazon service ), satellite(s), or other infrastructure that can be useful to his attacking plans. Such an infrastructure can be a set of antennas, lasers, Software Defined Radios (SDR) or other equipment able to transmit the desired signals. Such equipment can be fixed on ground, mounted on vehicles like trucks, ships, aircraft, or also installed on board of satellites.","url":"https://spaceshield.esa.int/techniques/T1583"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1583.001","url":"https://spaceshield.esa.int/techniques/T1583/001"}]},{"id":"SSH.T1583.003","stixId":"attack-pattern--60d05fde-dfb1-43b1-938f-61b18ccab95c","name":"Acquire jamming equipment","description":"Antennas, lasers, or other equipment able to jam a radio or visible-light frequency can be useful to prevent communication or an image acquisition. These instruments can be fixed on ground, mounted on vehicles like trucks, ships, aircraft, or also installed on board of satellites. (Citation: European Space Agency) (Citation: SRC011) (Citation: SRC037)","url":"https://spaceshield.esa.int/techniques/T1583/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1583.003 Acquire jamming equipment","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[{"id":"SSH.T1583","stixId":"attack-pattern--b36d226e-497b-4c01-99d1-cf684cc96772","name":"Acquire or Build Infrastructure","description":"An attacker can acquire a Ground Segment, a Ground Station service (e.g. Amazon service ), satellite(s), or other infrastructure that can be useful to his attacking plans. Such an infrastructure can be a set of antennas, lasers, Software Defined Radios (SDR) or other equipment able to transmit the desired signals. Such equipment can be fixed on ground, mounted on vehicles like trucks, ships, aircraft, or also installed on board of satellites.","url":"https://spaceshield.esa.int/techniques/T1583"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1583.003","url":"https://spaceshield.esa.int/techniques/T1583/003"},{"source":"European Space Agency","url":"https://www.esa.int"},{"source":"SRC011","url":"https://interestingengineering.com/innovation/us-space-forces-first-offensive-weapon-is-a-satellite-jammer"},{"source":"SRC037","url":"https://www.space.com/gps-signal-jamming-explainer-russia-ukraine-invasion"}]},{"id":"SSH.T1583.004","stixId":"attack-pattern--b16dcdcb-0949-4c24-b4bc-5b750fc07d5f","name":"Acquire Satellite","description":"Launching a new satellite or gaining control of an existing satellite.","url":"https://spaceshield.esa.int/techniques/T1583/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1583.004 Acquire Satellite","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T1583","stixId":"attack-pattern--b36d226e-497b-4c01-99d1-cf684cc96772","name":"Acquire or Build Infrastructure","description":"An attacker can acquire a Ground Segment, a Ground Station service (e.g. Amazon service ), satellite(s), or other infrastructure that can be useful to his attacking plans. Such an infrastructure can be a set of antennas, lasers, Software Defined Radios (SDR) or other equipment able to transmit the desired signals. Such equipment can be fixed on ground, mounted on vehicles like trucks, ships, aircraft, or also installed on board of satellites.","url":"https://spaceshield.esa.int/techniques/T1583"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1583.004","url":"https://spaceshield.esa.int/techniques/T1583/004"}]},{"id":"SSH.T1583.005","stixId":"attack-pattern--2c910a34-7018-4009-a8f9-dfddbd5a2c3f","name":"Rent ground segment as a service","description":"Building it, or renting a cloud based Ground Segment (e.g., AWS) ","url":"https://spaceshield.esa.int/techniques/T1583/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1583.005 Rent ground segment as a service","platforms":["None"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T1583","stixId":"attack-pattern--b36d226e-497b-4c01-99d1-cf684cc96772","name":"Acquire or Build Infrastructure","description":"An attacker can acquire a Ground Segment, a Ground Station service (e.g. Amazon service ), satellite(s), or other infrastructure that can be useful to his attacking plans. Such an infrastructure can be a set of antennas, lasers, Software Defined Radios (SDR) or other equipment able to transmit the desired signals. Such equipment can be fixed on ground, mounted on vehicles like trucks, ships, aircraft, or also installed on board of satellites.","url":"https://spaceshield.esa.int/techniques/T1583"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1583.005","url":"https://spaceshield.esa.int/techniques/T1583/005"}]},{"id":"SSH.T1584","stixId":"attack-pattern--b9691265-8543-45c2-8c67-4fb9e976c7b8","name":"Compromise Infrastructure","description":"It is similar to the acquisition of the infrastructure [T1583](Citation: MITRE ATT&CK) with the difference that in these cases adversaries break into them by compromising their security. They can get access to a ground segment, gain control of satellites, etc. Compromised satellites cam be used, apart from the 'typical' attacks, also e.g. for kinetic attacks, for creating botnets (e.g. for RF jamming, etc.). Such a threat is even bigger in case of compromise of numerous satellites part of a large LEO constellation of a 'New Space' mission. \n\nRelevant standards: (Citation: SRC038) ","url":"https://spaceshield.esa.int/techniques/T1584","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1584 Compromise Infrastructure","platforms":["Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2002","stixId":"course-of-action--f340a10b-0cc2-4ade-bf9c-5eff01877b3a","name":"Authentication","description":"Authentication permits a secure access to the resource, verifying the actor's identity. It also protects a command or a message from spoofing or modifications. CCSDS SDLS protocol incorporates authentication through MAC. Authentication protects from attacks aiming to access unauthorized resources, to spoof legitimate users, or to manipulate data and communications. (Citation: SRC008) (Citation: SRC017) (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2002"}],"externalReferences":[{"source":"mitre-attack","id":"T1584","url":"https://spaceshield.esa.int/techniques/T1584"},{"source":"SRC038","url":"https://ecss.nl/"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1584.001","stixId":"attack-pattern--98c67e39-b5ee-4618-908c-c1106c6a8624","name":"Compromise Ground Segment","description":"If a Ground System is located in a remote area with limited physical security controls, a physical violation of the site is possible. There should be authentication systems implemented that make difficult to use it without a proper authorization. (Citation: SRC013) (Citation: APT attack compromising Newsat infrastructure for months)","url":"https://spaceshield.esa.int/techniques/T1584/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1584.001 Compromise Ground Segment","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T1584","stixId":"attack-pattern--b9691265-8543-45c2-8c67-4fb9e976c7b8","name":"Compromise Infrastructure","description":"It is similar to the acquisition of the infrastructure [T1583](Citation: MITRE ATT&CK) with the difference that in these cases adversaries break into them by compromising their security. They can get access to a ground segment, gain control of satellites, etc. Compromised satellites cam be used, apart from the 'typical' attacks, also e.g. for kinetic attacks, for creating botnets (e.g. for RF jamming, etc.). Such a threat is even bigger in case of compromise of numerous satellites part of a large LEO constellation of a 'New Space' mission. \n\nRelevant standards: (Citation: SRC038) ","url":"https://spaceshield.esa.int/techniques/T1584"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1584.001","url":"https://spaceshield.esa.int/techniques/T1584/001"},{"source":"SRC013","url":"https://doi.org/10.1093/cybsec/tyac008"},{"source":"APT attack compromising Newsat infrastructure for months","url":"https://securityaffairs.com/50685/intelligence/newsat-satellite-hacked.html"}]},{"id":"SSH.T1584.002","stixId":"attack-pattern--9536d9b1-1628-4ada-9f66-8a72bcf5611d","name":"Compromise Satellite(s)","description":"Compromised or malicious satellites might be abused by adversaries to achieve kinetic effects on other satellites in orbit, such as sensor interference or manipulation. (Citation: SRC013)","url":"https://spaceshield.esa.int/techniques/T1584/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1584.002 Compromise Satellite(s)","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T1584","stixId":"attack-pattern--b9691265-8543-45c2-8c67-4fb9e976c7b8","name":"Compromise Infrastructure","description":"It is similar to the acquisition of the infrastructure [T1583](Citation: MITRE ATT&CK) with the difference that in these cases adversaries break into them by compromising their security. They can get access to a ground segment, gain control of satellites, etc. Compromised satellites cam be used, apart from the 'typical' attacks, also e.g. for kinetic attacks, for creating botnets (e.g. for RF jamming, etc.). Such a threat is even bigger in case of compromise of numerous satellites part of a large LEO constellation of a 'New Space' mission. \n\nRelevant standards: (Citation: SRC038) ","url":"https://spaceshield.esa.int/techniques/T1584"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1584.002","url":"https://spaceshield.esa.int/techniques/T1584/002"},{"source":"SRC013","url":"https://doi.org/10.1093/cybsec/tyac008"}]},{"id":"SSH.T1591","stixId":"attack-pattern--c4522b85-454a-40a4-b608-de5ffd0f9dfa","name":"Gather Victim Org Information","description":"Adversaries may gather information about the victim's organization that can be used during targeting. Information about an organization may include a variety of details, including the names of divisions/departments, specifics of business operations, as well as the roles and responsibilities of key employees. (Citation: MITRE ATT&CK)\n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://spaceshield.esa.int/techniques/T1591","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1591 Gather Victim Org Information","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2035","stixId":"course-of-action--8a91aa64-daa2-4d27-90df-7132297fca2e","name":"Proper Information Classification and Flow-Down Guidelines","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2035"},{"id":"SSH.M1017","stixId":"course-of-action--5b9ac7d7-56b5-4c43-8355-1c5a0701ef0f","name":"User Training","description":"Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful spear phishing, social engineering, and other techniques that involve user interaction. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1017"}],"externalReferences":[{"source":"mitre-attack","id":"T1591","url":"https://spaceshield.esa.int/techniques/T1591"},{"source":"SRC038","url":"https://ecss.nl/"},{"source":"ESA Security Framework","url":"https://www.esa.int"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1591.005","stixId":"attack-pattern--4eb85331-b756-4047-929d-07e1b2f0aaa4","name":"Search Closed Sources","description":"Adversaries may search and gather information about victims from closed sources that can be used during targeting. Information about victims may be available for purchase from reputable private sources and databases, such as paid subscriptions to feeds of technical/threat intelligence data. Adversaries may also purchase information from less-reputable sources such as dark web or cybercrime black-markets. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1591/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1591.005 Search Closed Sources","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T1591","stixId":"attack-pattern--c4522b85-454a-40a4-b608-de5ffd0f9dfa","name":"Gather Victim Org Information","description":"Adversaries may gather information about the victim's organization that can be used during targeting. Information about an organization may include a variety of details, including the names of divisions/departments, specifics of business operations, as well as the roles and responsibilities of key employees. (Citation: MITRE ATT&CK)\n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://spaceshield.esa.int/techniques/T1591"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1591.005","url":"https://spaceshield.esa.int/techniques/T1591/005"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1591.006","stixId":"attack-pattern--a9cf633a-5c71-458d-807d-3376ac57c1de","name":"Open Source Intelligence (OSINT)","description":"An attacker can purchased relevant information from open sources like available websites or social media, published documents, etc.","url":"https://spaceshield.esa.int/techniques/T1591/006","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1591.006 Open Source Intelligence (OSINT)","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T1591","stixId":"attack-pattern--c4522b85-454a-40a4-b608-de5ffd0f9dfa","name":"Gather Victim Org Information","description":"Adversaries may gather information about the victim's organization that can be used during targeting. Information about an organization may include a variety of details, including the names of divisions/departments, specifics of business operations, as well as the roles and responsibilities of key employees. (Citation: MITRE ATT&CK)\n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://spaceshield.esa.int/techniques/T1591"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1591.006","url":"https://spaceshield.esa.int/techniques/T1591/006"}]},{"id":"SSH.T1591.007","stixId":"attack-pattern--2c8ce166-6621-4f11-833c-5b47823fa1c2","name":"Spear Phishing attacks","description":"Spear Phishing attacks, targeting engineers, etc., to get information about the design, technologies used, etc. \nSpear Phishing attacks can be performed by using any of the techniques mentioned in T1598 (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1591/007","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1591.007 Spear Phishing attacks","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T1591","stixId":"attack-pattern--c4522b85-454a-40a4-b608-de5ffd0f9dfa","name":"Gather Victim Org Information","description":"Adversaries may gather information about the victim's organization that can be used during targeting. Information about an organization may include a variety of details, including the names of divisions/departments, specifics of business operations, as well as the roles and responsibilities of key employees. (Citation: MITRE ATT&CK)\n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://spaceshield.esa.int/techniques/T1591"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1591.007","url":"https://spaceshield.esa.int/techniques/T1591/007"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1598","stixId":"attack-pattern--3f890073-5b11-4cc2-91b7-59a5e2ce52ce","name":"Phishing for Information","description":"\"Adversaries may send phishing messages to elicit sensitive information that can be used during targeting. Phishing for information is an attempt to trick targets into divulging information, frequently credentials or other actionable information.\" (Citation: MITRE ATT&CK). Gathering data from the victim is the final objective.","url":"https://spaceshield.esa.int/techniques/T1598","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1598 Phishing for Information","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M1017","stixId":"course-of-action--5b9ac7d7-56b5-4c43-8355-1c5a0701ef0f","name":"User Training","description":"Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful spear phishing, social engineering, and other techniques that involve user interaction. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1017"}],"externalReferences":[{"source":"mitre-attack","id":"T1598","url":"https://spaceshield.esa.int/techniques/T1598"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1598.001","stixId":"attack-pattern--d862ba4f-a165-482c-964d-3a441445d157","name":"Spear Phishing to Ground Segment Operators","description":"The attack can target Ground Segment operators, to gain information useful to target the Ground Segment later. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1598/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1598.001 Spear Phishing to Ground Segment Operators","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T1598","stixId":"attack-pattern--3f890073-5b11-4cc2-91b7-59a5e2ce52ce","name":"Phishing for Information","description":"\"Adversaries may send phishing messages to elicit sensitive information that can be used during targeting. Phishing for information is an attempt to trick targets into divulging information, frequently credentials or other actionable information.\" (Citation: MITRE ATT&CK). Gathering data from the victim is the final objective.","url":"https://spaceshield.esa.int/techniques/T1598"}],"mitigations":[{"id":"SSH.M1017","stixId":"course-of-action--5b9ac7d7-56b5-4c43-8355-1c5a0701ef0f","name":"User Training","description":"Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful spear phishing, social engineering, and other techniques that involve user interaction. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1017"}],"externalReferences":[{"source":"mitre-attack","id":"T1598.001","url":"https://spaceshield.esa.int/techniques/T1598/001"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T1598.002","stixId":"attack-pattern--88b2403d-63d3-4d97-9943-f7fe207a08e6","name":"Spear Phishing to Industry/Space Agencies","description":"The attack can target Industries or Space Agencies, that are involved in development, and it could result in information leaking, that can be used to target the attack or to produce some specific hardware. In this last case it can even affect supply chain. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T1598/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1598.002 Spear Phishing to Industry/Space Agencies","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T1598","stixId":"attack-pattern--3f890073-5b11-4cc2-91b7-59a5e2ce52ce","name":"Phishing for Information","description":"\"Adversaries may send phishing messages to elicit sensitive information that can be used during targeting. Phishing for information is an attempt to trick targets into divulging information, frequently credentials or other actionable information.\" (Citation: MITRE ATT&CK). Gathering data from the victim is the final objective.","url":"https://spaceshield.esa.int/techniques/T1598"}],"mitigations":[{"id":"SSH.M1017","stixId":"course-of-action--5b9ac7d7-56b5-4c43-8355-1c5a0701ef0f","name":"User Training","description":"Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful spear phishing, social engineering, and other techniques that involve user interaction. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1017"}],"externalReferences":[{"source":"mitre-attack","id":"T1598.002","url":"https://spaceshield.esa.int/techniques/T1598/002"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T1611","stixId":"attack-pattern--606b44a5-baf1-4d8a-be3a-65b831333afe","name":"Escape to Host","description":"If containers or hypervisors are used, an attacker could overcome the container fences and gain access to the host system. Separations between applications may be defeated, and malicious operations could affect other functionalities. This attack can leverage common utilities, schedulers, shared memory, or vulnerabilities. (Citation: European Space Agency)\n\n\"Gaining access to the host may provide the adversary with the opportunity to achieve follow-on objectives, such as establishing persistence, moving laterally within the environment, or setting up a command-and-control channel on the host.\" (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1611","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T1611 Escape to Host","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0004","name":"Privilege Escalation","shortname":"privilege-escalation"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2064","stixId":"course-of-action--bb0a83b2-1e13-4f80-8da5-4d75a06faded","name":"Detection techniques of exploitation attempts","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2064"},{"id":"SSH.M2063","stixId":"course-of-action--23966f59-9560-4868-8652-2f397e597e64","name":"Patching to the latest available software version","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2063"}],"externalReferences":[{"source":"mitre-attack","id":"T1611","url":"https://spaceshield.esa.int/techniques/T1611"},{"source":"European Space Agency","url":"https://www.esa.int"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T1611.001","stixId":"attack-pattern--d6766a4b-8372-4474-8df0-4603c27b3826","name":"Exploitation of vulnerabilities","description":"An attacker can exploiting unpatched/outdated containers or hypervisors to escape it ","url":"https://spaceshield.esa.int/techniques/T1611/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T1611.001 Exploitation of vulnerabilities","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0004","name":"Privilege Escalation","shortname":"privilege-escalation"}],"parentTechniques":[{"id":"SSH.T1611","stixId":"attack-pattern--606b44a5-baf1-4d8a-be3a-65b831333afe","name":"Escape to Host","description":"If containers or hypervisors are used, an attacker could overcome the container fences and gain access to the host system. Separations between applications may be defeated, and malicious operations could affect other functionalities. This attack can leverage common utilities, schedulers, shared memory, or vulnerabilities. (Citation: European Space Agency)\n\n\"Gaining access to the host may provide the adversary with the opportunity to achieve follow-on objectives, such as establishing persistence, moving laterally within the environment, or setting up a command-and-control channel on the host.\" (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T1611"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T1611.001","url":"https://spaceshield.esa.int/techniques/T1611/001"}]},{"id":"SSH.T2001","stixId":"attack-pattern--0612139c-dca0-44e0-b2e8-ae2186f787fc","name":"Active Scanning (RF/Optical)","description":"The technique is the same of the Passive Interception, the difference is that the attacker initiates interaction with the space target trying to trigger potential responses (even error messages) by actively sending signals/packets. The scan can be similar to a \"brute force\" attack, in the sense that the objective is 'guess' the used frequencies and protocols to obtain a reply. This is why authentication is also included here as a mitigation measure (provided that it does not solicit any response to not authenticated signals). On the other hand, since sending telemetry data won't trigger any response due to their nature (even if they are fully compliant with the expected format), are not included here as a subtechniques. \n\nStandard/references: (Citation: SRC038) (Citation: SRC008) (Citation: SRC039) (Citation: SRC014)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)\n","url":"https://attack.mitre.org/techniques/T2001","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2001 Active Scanning (RF/Optical)","platforms":["Ground Segment","Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2030","stixId":"course-of-action--e953c9fb-c9d8-4ec3-9315-b4fd6e3f1db2","name":"Usage of directive transmit antenna","description":"Usage of directive transmit antenna (incl. potentially optical links, antennas with more focused patterns, etc.)","url":"https://spaceshield.esa.int/mitigations/M2030"},{"id":"SSH.M2014","stixId":"course-of-action--f8c7ed24-c26c-49c7-a78f-74be6cca3d95","name":"Spread Spectrum","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2014"},{"id":"SSH.M2015","stixId":"course-of-action--d281c8ce-6a5e-4b22-b808-0f714ffcc4c3","name":"Cryptographic DSSS sequence","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof.  If the DSSS sequence is protected by a cryptographic sequence, a cryptographic key is needed to predict the spreading sequence's behavior. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2015"},{"id":"SSH.M2016","stixId":"course-of-action--53d273af-6461-4730-a1ff-a754332fa4a0","name":"Frequency Hopping","description":"Frequency Hopping is a system to regularly change the carrier frequency according to a specific pattern. This procedure makes interception more difficult and protects the signal from interference, either deliberated or not.  (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2016"},{"id":"SSH.M2002","stixId":"course-of-action--f340a10b-0cc2-4ade-bf9c-5eff01877b3a","name":"Authentication","description":"Authentication permits a secure access to the resource, verifying the actor's identity. It also protects a command or a message from spoofing or modifications. CCSDS SDLS protocol incorporates authentication through MAC. Authentication protects from attacks aiming to access unauthorized resources, to spoof legitimate users, or to manipulate data and communications. (Citation: SRC008) (Citation: SRC017) (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2002"},{"id":"SSH.M2003","stixId":"course-of-action--d87c5194-1a09-4d5e-a8f8-5fb53a5e26b9","name":"Encryption of communications","description":"Encryption of communications  hides the message content to unauthorized eavesdropper, ensuring confidentiality. \n\nThe Space Data Link Security Protocol is a standard defined how to apply encryption, authenticated encryption and encryption only (not recommended) for the CCSDS communication at the Data Link Layer.\n\nPayload traffic, if related to network communications, can use specific traffic protocols, e.g., QPEP. Range data shall be also encrypted. (Citation: SRC008) (Citation: SRC017) (Citation: SRC029)","url":"https://spaceshield.esa.int/mitigations/M2003"},{"id":"SSH.M2033","stixId":"course-of-action--7efe8fbe-f74b-4c95-97e3-e6d665c50c05","name":"High-power up-link","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2033"}],"externalReferences":[{"source":"mitre-attack","id":"T2001","url":"https://attack.mitre.org/techniques/T2001"},{"source":"SRC039","url":"https://public.ccsds.org/Pubs/352x0b2.pdf"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"SRC038","url":"https://ecss.nl/"},{"source":"ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz","url":"https://www.itu.int/dms_pubrec/itu-r/rec/s/R-REC-S.1428-1-200102-I!!PDF-E.pdf"}]},{"id":"SSH.T2001.001","stixId":"attack-pattern--9174a0f5-9688-46e6-93cf-c86371136b49","name":"Telecommand Protocol Scanning","description":"An attacker tries to gain knowledge about the Telecommand implementation, including the authentication and encryption status. (Citation: SRC012)\n\nStandard/references: (Citation: SRC003) (Citation: SRC005) (Citation: SRC009)","url":"https://spaceshield.esa.int/techniques/T2001/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2001.001 Telecommand Protocol Scanning","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2001","stixId":"attack-pattern--0612139c-dca0-44e0-b2e8-ae2186f787fc","name":"Active Scanning (RF/Optical)","description":"The technique is the same of the Passive Interception, the difference is that the attacker initiates interaction with the space target trying to trigger potential responses (even error messages) by actively sending signals/packets. The scan can be similar to a \"brute force\" attack, in the sense that the objective is 'guess' the used frequencies and protocols to obtain a reply. This is why authentication is also included here as a mitigation measure (provided that it does not solicit any response to not authenticated signals). On the other hand, since sending telemetry data won't trigger any response due to their nature (even if they are fully compliant with the expected format), are not included here as a subtechniques. \n\nStandard/references: (Citation: SRC038) (Citation: SRC008) (Citation: SRC039) (Citation: SRC014)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)\n","url":"https://attack.mitre.org/techniques/T2001"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2001.001","url":"https://spaceshield.esa.int/techniques/T2001/001"},{"source":"SRC005","url":"https://public.ccsds.org/Pubs/231x0b4e0.pdf"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T2001.002","stixId":"attack-pattern--eec1a0b8-9b2c-469b-8385-90bd242930ec","name":"Telemetry Protocol Scanning","description":"An attacker tries to gain knowledge about the Telemetry implementation, including the authentication and encryption status. (Citation: SRC012)\n\nStandard/references: (Citation: SRC003) (Citation: SRC006) (Citation: SRC010)","url":"https://spaceshield.esa.int/techniques/T2001/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2001.002 Telemetry Protocol Scanning","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2001","stixId":"attack-pattern--0612139c-dca0-44e0-b2e8-ae2186f787fc","name":"Active Scanning (RF/Optical)","description":"The technique is the same of the Passive Interception, the difference is that the attacker initiates interaction with the space target trying to trigger potential responses (even error messages) by actively sending signals/packets. The scan can be similar to a \"brute force\" attack, in the sense that the objective is 'guess' the used frequencies and protocols to obtain a reply. This is why authentication is also included here as a mitigation measure (provided that it does not solicit any response to not authenticated signals). On the other hand, since sending telemetry data won't trigger any response due to their nature (even if they are fully compliant with the expected format), are not included here as a subtechniques. \n\nStandard/references: (Citation: SRC038) (Citation: SRC008) (Citation: SRC039) (Citation: SRC014)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)\n","url":"https://attack.mitre.org/techniques/T2001"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2001.002","url":"https://spaceshield.esa.int/techniques/T2001/002"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC006","url":"https://public.ccsds.org/Pubs/131x0b4.pdf"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T2001.003","stixId":"attack-pattern--92f0102c-accc-4e92-bac4-b8a3855588b2","name":"Mission specific channel scanning","description":"An attacker tries to gain knowledge about a payload dedicated channel communication, peculiar in a specific mission. The channel can be managed by a different company than the owner of the satellite. Scanning includes authentication/encryption schemes and medium access control. (Citation: SRC012)\n\nStandard/references: (Citation: SRC003)","url":"https://spaceshield.esa.int/techniques/T2001/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2001.003 Mission specific channel scanning","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2001","stixId":"attack-pattern--0612139c-dca0-44e0-b2e8-ae2186f787fc","name":"Active Scanning (RF/Optical)","description":"The technique is the same of the Passive Interception, the difference is that the attacker initiates interaction with the space target trying to trigger potential responses (even error messages) by actively sending signals/packets. The scan can be similar to a \"brute force\" attack, in the sense that the objective is 'guess' the used frequencies and protocols to obtain a reply. This is why authentication is also included here as a mitigation measure (provided that it does not solicit any response to not authenticated signals). On the other hand, since sending telemetry data won't trigger any response due to their nature (even if they are fully compliant with the expected format), are not included here as a subtechniques. \n\nStandard/references: (Citation: SRC038) (Citation: SRC008) (Citation: SRC039) (Citation: SRC014)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)\n","url":"https://attack.mitre.org/techniques/T2001"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2001.003","url":"https://spaceshield.esa.int/techniques/T2001/003"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T2001.004","stixId":"attack-pattern--99ed35cb-780c-49ed-a411-eab574efc7b0","name":"Remote Vulnerability Scanning","description":"As  'New Space' missions are typically using COTS or OSS, remote vulnerability scanning can also be a technique (may require authentication).","url":"https://spaceshield.esa.int/techniques/T2001/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2001.004 Remote Vulnerability Scanning","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2001","stixId":"attack-pattern--0612139c-dca0-44e0-b2e8-ae2186f787fc","name":"Active Scanning (RF/Optical)","description":"The technique is the same of the Passive Interception, the difference is that the attacker initiates interaction with the space target trying to trigger potential responses (even error messages) by actively sending signals/packets. The scan can be similar to a \"brute force\" attack, in the sense that the objective is 'guess' the used frequencies and protocols to obtain a reply. This is why authentication is also included here as a mitigation measure (provided that it does not solicit any response to not authenticated signals). On the other hand, since sending telemetry data won't trigger any response due to their nature (even if they are fully compliant with the expected format), are not included here as a subtechniques. \n\nStandard/references: (Citation: SRC038) (Citation: SRC008) (Citation: SRC039) (Citation: SRC014)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)\n","url":"https://attack.mitre.org/techniques/T2001"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2001.004","url":"https://spaceshield.esa.int/techniques/T2001/004"}]},{"id":"SSH.T2002","stixId":"attack-pattern--b51a7f9d-db74-4c11-8f41-7d15e3d06ead","name":"Gather Victim Mission Information","description":"An attacker tries to gather information about a specific mission to target it. An attacker can find information about firmware, software, hardware, frequencies, protocols, cryptographic algorithms, spacecraft descriptors used in a mission, and other knowledge like the spacecraft design, architecture, position and trajectory. The application of this technique in the supply chain can lead to a software/tools/datasheets or a design leak. If COTS or open-source components are used, information can be easily gathered online or from the producing company. \n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://attack.mitre.org/techniques/T2002","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2002 Gather Victim Mission Information","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M1017","stixId":"course-of-action--5b9ac7d7-56b5-4c43-8355-1c5a0701ef0f","name":"User Training","description":"Train users to be aware of access or manipulation attempts by an adversary to reduce the risk of successful spear phishing, social engineering, and other techniques that involve user interaction. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1017"},{"id":"SSH.M2035","stixId":"course-of-action--8a91aa64-daa2-4d27-90df-7132297fca2e","name":"Proper Information Classification and Flow-Down Guidelines","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2035"}],"externalReferences":[{"source":"mitre-attack","id":"T2002","url":"https://attack.mitre.org/techniques/T2002"},{"source":"SRC038","url":"https://ecss.nl/"},{"source":"ESA Security Framework","url":"https://www.esa.int"}]},{"id":"SSH.T2002.009","stixId":"attack-pattern--8f783f56-0bed-45fb-a7bd-1cbb846ed217","name":"Search Closed Sources","description":"Adversaries may search and gather information about victims from closed sources that can be used during targeting. Information about victims may be available for purchase from reputable private sources and databases, such as paid subscriptions to feeds of technical/threat intelligence data. Adversaries may also purchase information from less-reputable sources such as dark web or cybercrime black-markets. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2002/009","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2002.009 Search Closed Sources","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2002","stixId":"attack-pattern--b51a7f9d-db74-4c11-8f41-7d15e3d06ead","name":"Gather Victim Mission Information","description":"An attacker tries to gather information about a specific mission to target it. An attacker can find information about firmware, software, hardware, frequencies, protocols, cryptographic algorithms, spacecraft descriptors used in a mission, and other knowledge like the spacecraft design, architecture, position and trajectory. The application of this technique in the supply chain can lead to a software/tools/datasheets or a design leak. If COTS or open-source components are used, information can be easily gathered online or from the producing company. \n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://attack.mitre.org/techniques/T2002"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2002.009","url":"https://spaceshield.esa.int/techniques/T2002/009"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2002.010","stixId":"attack-pattern--cb8e41f1-9494-4c17-93f6-92d5beca9129","name":"Spear Phishing attacks","description":"Spear Phishing attacks, targeting engineers, etc., to get information about the design, technologies used, etc. Spear Phishing attacks can be performed by using any of the techniques mentioned in T1598 (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2002/010","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2002.010 Spear Phishing attacks","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2002","stixId":"attack-pattern--b51a7f9d-db74-4c11-8f41-7d15e3d06ead","name":"Gather Victim Mission Information","description":"An attacker tries to gather information about a specific mission to target it. An attacker can find information about firmware, software, hardware, frequencies, protocols, cryptographic algorithms, spacecraft descriptors used in a mission, and other knowledge like the spacecraft design, architecture, position and trajectory. The application of this technique in the supply chain can lead to a software/tools/datasheets or a design leak. If COTS or open-source components are used, information can be easily gathered online or from the producing company. \n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://attack.mitre.org/techniques/T2002"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2002.010","url":"https://spaceshield.esa.int/techniques/T2002/010"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2002.011","stixId":"attack-pattern--311c35dd-939c-40c8-8c0f-c240ac02aab6","name":"Open Source Intelligence (OSINT)","description":"An attacker can purchased relevant information from open sources like available websites or social media, published documents, etc.","url":"https://spaceshield.esa.int/techniques/T2002/011","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2002.011 Open Source Intelligence (OSINT)","platforms":["None"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2002","stixId":"attack-pattern--b51a7f9d-db74-4c11-8f41-7d15e3d06ead","name":"Gather Victim Mission Information","description":"An attacker tries to gather information about a specific mission to target it. An attacker can find information about firmware, software, hardware, frequencies, protocols, cryptographic algorithms, spacecraft descriptors used in a mission, and other knowledge like the spacecraft design, architecture, position and trajectory. The application of this technique in the supply chain can lead to a software/tools/datasheets or a design leak. If COTS or open-source components are used, information can be easily gathered online or from the producing company. \n\nRelevant standards: (Citation: SRC038)(Citation: ESA Security Framework)","url":"https://attack.mitre.org/techniques/T2002"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2002.011","url":"https://spaceshield.esa.int/techniques/T2002/011"}]},{"id":"SSH.T2004","stixId":"attack-pattern--61947c2f-4ae8-4292-8ff8-901c076f565c","name":"Passive Interception (RF/Optical)","description":"An attacker tries to gain knowledge about which communication protocols are used and how, looking for manners to exploit them. This can be executed intercepting, recording, and analyzing the signal to extract as more information as possible on the communication protocols. For example, different protocols can apply SDLS security to a part of the services. Optical link can be used for satellite feeder and intersat links, for some special payloads, or for deep space communications (availability problem caused by clouds should be considered if the receiver is on the Earth). If the downlink signal is sent by a far spacecraft, the beam covers a large ground area on the Earth, and the possible scanning area is extended. Receiving a satellite signal is simple and cheap, various open-source projects exist, e.g., NyanSat. (Citation: SRC012) (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC038)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2004","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2004 Passive Interception (RF/Optical)","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2031","stixId":"course-of-action--e51b483e-dc98-434b-9ed6-553468d8b22c","name":"Padding","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2031"},{"id":"SSH.M2016","stixId":"course-of-action--53d273af-6461-4730-a1ff-a754332fa4a0","name":"Frequency Hopping","description":"Frequency Hopping is a system to regularly change the carrier frequency according to a specific pattern. This procedure makes interception more difficult and protects the signal from interference, either deliberated or not.  (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2016"},{"id":"SSH.M2003","stixId":"course-of-action--d87c5194-1a09-4d5e-a8f8-5fb53a5e26b9","name":"Encryption of communications","description":"Encryption of communications  hides the message content to unauthorized eavesdropper, ensuring confidentiality. \n\nThe Space Data Link Security Protocol is a standard defined how to apply encryption, authenticated encryption and encryption only (not recommended) for the CCSDS communication at the Data Link Layer.\n\nPayload traffic, if related to network communications, can use specific traffic protocols, e.g., QPEP. Range data shall be also encrypted. (Citation: SRC008) (Citation: SRC017) (Citation: SRC029)","url":"https://spaceshield.esa.int/mitigations/M2003"},{"id":"SSH.M2014","stixId":"course-of-action--f8c7ed24-c26c-49c7-a78f-74be6cca3d95","name":"Spread Spectrum","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2014"},{"id":"SSH.M2032","stixId":"course-of-action--170597f4-33a4-4b2c-ba1b-7358d68bdf02","name":"Bulk data link encryption","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2032"},{"id":"SSH.M2030","stixId":"course-of-action--e953c9fb-c9d8-4ec3-9315-b4fd6e3f1db2","name":"Usage of directive transmit antenna","description":"Usage of directive transmit antenna (incl. potentially optical links, antennas with more focused patterns, etc.)","url":"https://spaceshield.esa.int/mitigations/M2030"},{"id":"SSH.M2015","stixId":"course-of-action--d281c8ce-6a5e-4b22-b808-0f714ffcc4c3","name":"Cryptographic DSSS sequence","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof.  If the DSSS sequence is protected by a cryptographic sequence, a cryptographic key is needed to predict the spreading sequence's behavior. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2015"}],"externalReferences":[{"source":"mitre-attack","id":"T2004","url":"https://attack.mitre.org/techniques/T2004"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"SRC038","url":"https://ecss.nl/"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"},{"source":"ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz","url":"https://www.itu.int/dms_pubrec/itu-r/rec/s/R-REC-S.1428-1-200102-I!!PDF-E.pdf"}]},{"id":"SSH.T2004.001","stixId":"attack-pattern--7588978e-8f3a-42a0-83ee-22f8b159b71d","name":"Telecommand Protocol Interception","description":"An attacker tries to gain knowledge about the Telecommand implementation, including the authentication and encryption status. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC005) (Citation: SRC009)","url":"https://spaceshield.esa.int/techniques/T2004/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2004.001 Telecommand Protocol Interception","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2004","stixId":"attack-pattern--61947c2f-4ae8-4292-8ff8-901c076f565c","name":"Passive Interception (RF/Optical)","description":"An attacker tries to gain knowledge about which communication protocols are used and how, looking for manners to exploit them. This can be executed intercepting, recording, and analyzing the signal to extract as more information as possible on the communication protocols. For example, different protocols can apply SDLS security to a part of the services. Optical link can be used for satellite feeder and intersat links, for some special payloads, or for deep space communications (availability problem caused by clouds should be considered if the receiver is on the Earth). If the downlink signal is sent by a far spacecraft, the beam covers a large ground area on the Earth, and the possible scanning area is extended. Receiving a satellite signal is simple and cheap, various open-source projects exist, e.g., NyanSat. (Citation: SRC012) (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC038)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2004"}],"mitigations":[{"id":"SSH.M2015","stixId":"course-of-action--d281c8ce-6a5e-4b22-b808-0f714ffcc4c3","name":"Cryptographic DSSS sequence","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof.  If the DSSS sequence is protected by a cryptographic sequence, a cryptographic key is needed to predict the spreading sequence's behavior. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2015"},{"id":"SSH.M2014","stixId":"course-of-action--f8c7ed24-c26c-49c7-a78f-74be6cca3d95","name":"Spread Spectrum","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2014"},{"id":"SSH.M2016","stixId":"course-of-action--53d273af-6461-4730-a1ff-a754332fa4a0","name":"Frequency Hopping","description":"Frequency Hopping is a system to regularly change the carrier frequency according to a specific pattern. This procedure makes interception more difficult and protects the signal from interference, either deliberated or not.  (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2016"}],"externalReferences":[{"source":"mitre-attack","id":"T2004.001","url":"https://spaceshield.esa.int/techniques/T2004/001"},{"source":"SRC005","url":"https://public.ccsds.org/Pubs/231x0b4e0.pdf"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T2004.002","stixId":"attack-pattern--e394ab7e-7882-43e0-8754-fef88449719c","name":"Telemetry Protocol Interception","description":"An attacker tries to gain knowledge about the Telemetry implementation, including the authentication and encryption status. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC006) (Citation: SRC010) (Citation: SRC024)","url":"https://spaceshield.esa.int/techniques/T2004/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2004.002 Telemetry Protocol Interception","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2004","stixId":"attack-pattern--61947c2f-4ae8-4292-8ff8-901c076f565c","name":"Passive Interception (RF/Optical)","description":"An attacker tries to gain knowledge about which communication protocols are used and how, looking for manners to exploit them. This can be executed intercepting, recording, and analyzing the signal to extract as more information as possible on the communication protocols. For example, different protocols can apply SDLS security to a part of the services. Optical link can be used for satellite feeder and intersat links, for some special payloads, or for deep space communications (availability problem caused by clouds should be considered if the receiver is on the Earth). If the downlink signal is sent by a far spacecraft, the beam covers a large ground area on the Earth, and the possible scanning area is extended. Receiving a satellite signal is simple and cheap, various open-source projects exist, e.g., NyanSat. (Citation: SRC012) (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC038)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2004"}],"mitigations":[{"id":"SSH.M2003","stixId":"course-of-action--d87c5194-1a09-4d5e-a8f8-5fb53a5e26b9","name":"Encryption of communications","description":"Encryption of communications  hides the message content to unauthorized eavesdropper, ensuring confidentiality. \n\nThe Space Data Link Security Protocol is a standard defined how to apply encryption, authenticated encryption and encryption only (not recommended) for the CCSDS communication at the Data Link Layer.\n\nPayload traffic, if related to network communications, can use specific traffic protocols, e.g., QPEP. Range data shall be also encrypted. (Citation: SRC008) (Citation: SRC017) (Citation: SRC029)","url":"https://spaceshield.esa.int/mitigations/M2003"}],"externalReferences":[{"source":"mitre-attack","id":"T2004.002","url":"https://spaceshield.esa.int/techniques/T2004/002"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC006","url":"https://public.ccsds.org/Pubs/131x0b4.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC024","url":"https://www.wired.com/story/nyansat-open-source-satellite-tracker/"}]},{"id":"SSH.T2004.003","stixId":"attack-pattern--bd34c9e7-f7f3-42ef-9400-f8c610246e13","name":"Mission specific Channel Interception","description":"An attacker tries to gain knowledge about a payload dedicated channel communication, peculiar in a specific mission. The channel can be managed by a different company than the owner of the satellite. Interception includes authentication/encryption schemes and medium access control. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003), (Citation: SRC024)","url":"https://spaceshield.esa.int/techniques/T2004/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2004.003 Mission specific Channel Interception","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2004","stixId":"attack-pattern--61947c2f-4ae8-4292-8ff8-901c076f565c","name":"Passive Interception (RF/Optical)","description":"An attacker tries to gain knowledge about which communication protocols are used and how, looking for manners to exploit them. This can be executed intercepting, recording, and analyzing the signal to extract as more information as possible on the communication protocols. For example, different protocols can apply SDLS security to a part of the services. Optical link can be used for satellite feeder and intersat links, for some special payloads, or for deep space communications (availability problem caused by clouds should be considered if the receiver is on the Earth). If the downlink signal is sent by a far spacecraft, the beam covers a large ground area on the Earth, and the possible scanning area is extended. Receiving a satellite signal is simple and cheap, various open-source projects exist, e.g., NyanSat. (Citation: SRC012) (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC038)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2004"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2004.003","url":"https://spaceshield.esa.int/techniques/T2004/003"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC024","url":"https://www.wired.com/story/nyansat-open-source-satellite-tracker/"}]},{"id":"SSH.T2004.005","stixId":"attack-pattern--679cc1ba-ffd1-46e0-adce-acc72c9ee5bf","name":"Traffic Analysis","description":"The attacker intends to determine which entities are communicating with each other without the ability to access the communicated information.","url":"https://spaceshield.esa.int/techniques/T2004/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2004.005 Traffic Analysis","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2004","stixId":"attack-pattern--61947c2f-4ae8-4292-8ff8-901c076f565c","name":"Passive Interception (RF/Optical)","description":"An attacker tries to gain knowledge about which communication protocols are used and how, looking for manners to exploit them. This can be executed intercepting, recording, and analyzing the signal to extract as more information as possible on the communication protocols. For example, different protocols can apply SDLS security to a part of the services. Optical link can be used for satellite feeder and intersat links, for some special payloads, or for deep space communications (availability problem caused by clouds should be considered if the receiver is on the Earth). If the downlink signal is sent by a far spacecraft, the beam covers a large ground area on the Earth, and the possible scanning area is extended. Receiving a satellite signal is simple and cheap, various open-source projects exist, e.g., NyanSat. (Citation: SRC012) (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC038)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2004"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2004.005","url":"https://spaceshield.esa.int/techniques/T2004/005"}]},{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2007 Develop/Obtain Capabilities","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2060","stixId":"course-of-action--dbc85852-b7bf-43e7-94ee-9fb6d459164b","name":"Establish processes, procedures, and security measures to protect cryptographic keys / key management","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2060"},{"id":"SSH.M2038","stixId":"course-of-action--70472a15-b052-4715-9b32-50dc82430399","name":"Source code review","description":"Static code analysis","url":"https://spaceshield.esa.int/mitigations/M2038"},{"id":"SSH.M2024","stixId":"course-of-action--d287d7ef-cf06-47be-b826-5df94e5de3bc","name":"Supply chain confidence","description":"Supply chain confidence is fundamental to mitigate risks or attacks related to supply chain, as introduction of backdoors or malicious capabilities in components that are going to be integrated in the system. Knowledge of the product chain, either hardware or software, reassurance in the measurements, tests, inspections, and certifications, can limit possible attack vectors and threats. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2024"},{"id":"SSH.M2040","stixId":"course-of-action--e88273bc-ed6b-4a33-90f0-849d94335b2a","name":"Secure PKI implementation","description":"Public Key Infrastructure (PKI) is a framework of roles, policies, hardware, software, and procedures necessary to securely create, manage, and use digital certificates and public-key encryption. In spacecraft systems, PKI plays a critical role in securing communications, ensuring that only authorized entities can issue commands or access sensitive data. This is especially important for space-to-ground communication, inter-satellite links, and internal command authentication.\n\nPKI enables strong authentication methods, far more secure than simple passwords, by binding public keys to the identities of spacecraft components, ground stations, or other authorized entities. This process is managed by a Certificate Authority (CA), which issues and manages digital certificates that verify identities and ensure the integrity of data transfers.\n\nPKI for spacecraft typically involves the secure registration, issuance, and management of certificates. ","url":"https://spaceshield.esa.int/mitigations/M2040"},{"id":"SSH.M2015","stixId":"course-of-action--d281c8ce-6a5e-4b22-b808-0f714ffcc4c3","name":"Cryptographic DSSS sequence","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof.  If the DSSS sequence is protected by a cryptographic sequence, a cryptographic key is needed to predict the spreading sequence's behavior. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2015"},{"id":"SSH.M2039","stixId":"course-of-action--aa986986-4991-487a-a3c6-e194968ac08c","name":"Fuzzing / testing","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2039"},{"id":"SSH.M2069","stixId":"course-of-action--fe50f2bc-a217-4d22-9cf2-83b0e4c811d7","name":"Strong authentication of Telecommands","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2069"}],"externalReferences":[{"source":"mitre-attack","id":"T2007","url":"https://attack.mitre.org/techniques/T2007"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"SRC038","url":"https://ecss.nl/"}]},{"id":"SSH.T2007.002","stixId":"attack-pattern--ca79e0bf-6cb5-4c11-90d8-0456a6c86f9a","name":"Code Signing Certificates","description":"Adversaries may buy and/or steal code signing certificates that can be used during targeting. Code signing is the process of digitally signing executables and scripts to confirm the software author and guarantee that the code has not been altered or corrupted. Code signing provides a level of authenticity for a program from the developer and a guarantee that the program has not been tampered with. Users and/or security tools may trust a signed piece of code more than an unsigned piece of code even if they don't know who issued the certificate or who the author is. (Citation: MITRE ATT&CK)\n\nStandard/references: (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2007/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.002 Code Signing Certificates","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.002","url":"https://spaceshield.esa.int/techniques/T2007/002"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2007.003","stixId":"attack-pattern--e48ffceb-b4f7-4eed-98e3-3e8184edebe8","name":"Digital Certificates","description":"CCSDS recommends two forms of credentials: X.509 certificates and protected simple authentication. There are risks for CCSDS systems utilizing credentials if an attacker gains control of the credential-management system and can issue credentials. If a compromised credential management process results, then there is a need to invalidate existing credentials and reissue all credentials. The authenticity of an X.509 certificate is dependent upon the digital signature of the CA attesting to the credential. If the digital signature algorithm used by the CA is of insufficient cryptographic strength, a credential may be spoofed. (Citation: MITRE ATT&CK)\n\nStandard/references: (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2007/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.003 Digital Certificates","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.003","url":"https://spaceshield.esa.int/techniques/T2007/003"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2007.004","stixId":"attack-pattern--a4591a4c-6b82-4ab1-b5ba-eeae499e4577","name":"DSSS or Frequency hopping sequence","description":"An attacker can guess the Spread Spectrum or the frequency hopping sequence, to reconstruct the received signal. (Citation: SRC021)\n\nStandard/references: (Citation: SRC021)","url":"https://spaceshield.esa.int/techniques/T2007/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.004 DSSS or Frequency hopping sequence","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[{"id":"SSH.M2015","stixId":"course-of-action--d281c8ce-6a5e-4b22-b808-0f714ffcc4c3","name":"Cryptographic DSSS sequence","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof.  If the DSSS sequence is protected by a cryptographic sequence, a cryptographic key is needed to predict the spreading sequence's behavior. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2015"}],"externalReferences":[{"source":"mitre-attack","id":"T2007.004","url":"https://spaceshield.esa.int/techniques/T2007/004"},{"source":"SRC021","url":"https://public.ccsds.org/Pubs/415x1b1.pdf"}]},{"id":"SSH.T2007.005","stixId":"attack-pattern--1f0d36fd-0631-4053-801b-3305467f2dbd","name":"Malicious supply chain capabilities","description":"Obtain or create malicious capabilities inside hardware or software intended to be used in a specific project. Injecting the malicious HW/SW in the right place is difficult, is also difficult being sure that the part will be integrated in a system. (Citation: SRC017)","url":"https://spaceshield.esa.int/techniques/T2007/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.005 Malicious supply chain capabilities","platforms":["None"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[{"id":"SSH.M1045","stixId":"course-of-action--20b66d7b-4c48-4e4a-a5a8-df4f5053fcfb","name":"Code signing","description":"Enforce binary and application integrity with digital signature verification to prevent untrusted code from executing. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1045"},{"id":"SSH.M2024","stixId":"course-of-action--d287d7ef-cf06-47be-b826-5df94e5de3bc","name":"Supply chain confidence","description":"Supply chain confidence is fundamental to mitigate risks or attacks related to supply chain, as introduction of backdoors or malicious capabilities in components that are going to be integrated in the system. Knowledge of the product chain, either hardware or software, reassurance in the measurements, tests, inspections, and certifications, can limit possible attack vectors and threats. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2024"}],"externalReferences":[{"source":"mitre-attack","id":"T2007.005","url":"https://spaceshield.esa.int/techniques/T2007/005"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T2007.006","stixId":"attack-pattern--85ce0dd8-7cf8-4a61-82ac-e70ebfe8a2e3","name":"Software vulnerabilities","description":"Exploiting unpatched/Outdated/Legacy COTS software deployed among the platform. COTS products are often highly complex, some of them involving tens of millions of lines of code, so that no one knows their content and behavior in detail. SDRs introduce protocol-independent software vulnerabilities into the communication system. (Citation: SRC012)","url":"https://spaceshield.esa.int/techniques/T2007/006","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.006 Software vulnerabilities","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.006","url":"https://spaceshield.esa.int/techniques/T2007/006"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T2007.008","stixId":"attack-pattern--44e0d79e-40bc-4d70-8cc1-2db2c0651fed","name":"Space Protocol Vulnerabilities","description":"Adversaries may acquire information about vulnerabilities that can be used during targeting. Adversaries may find vulnerability information by searching open databases or gaining access to closed vulnerability databases. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2007/008","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.008 Space Protocol Vulnerabilities","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.008","url":"https://spaceshield.esa.int/techniques/T2007/008"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2007.009","stixId":"attack-pattern--027dc75c-24f2-4e30-8c9c-eaf4483e7d2f","name":"Tools for attacking space systems","description":"An attacker can also develop or obtain tools that can be used to attack a space system. For example, tools can help with vulnerabilities research and tests. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2007/009","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.009 Tools for attacking space systems","platforms":["None"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.009","url":"https://spaceshield.esa.int/techniques/T2007/009"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2007.010","stixId":"attack-pattern--b07ccbe6-4621-4545-be4c-986dadfe8231","name":"TC/TM request forging","description":"An attacker can obtain capabilities to forge TC/TM or mission specific frames.","url":"https://spaceshield.esa.int/techniques/T2007/010","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.010 TC/TM request forging","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.010","url":"https://spaceshield.esa.int/techniques/T2007/010"}]},{"id":"SSH.T2007.011","stixId":"attack-pattern--07a1f7ba-8909-453e-a0d0-b7249f798bd2","name":"Cryptographic Keys","description":"An attacker can obtain master or session cryptographic keys or other cryptographic information used for authentication, encryption, etc.","url":"https://spaceshield.esa.int/techniques/T2007/011","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2007.011 Cryptographic Keys","platforms":["Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2007","stixId":"attack-pattern--ab9830c5-5779-4406-9e21-9046fba2a1b3","name":"Develop/Obtain Capabilities","description":"Adversaries may build, buy or steal capabilities that can be used during targeting. \n\nstandards: (Citation: SRC008)(Citation: SRC038)(Citation: SRC014)(Citation: SRC008)","url":"https://attack.mitre.org/techniques/T2007"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2007.011","url":"https://spaceshield.esa.int/techniques/T2007/011"}]},{"id":"SSH.T2008","stixId":"attack-pattern--e35b3790-b1b0-4098-873e-c24818228c32","name":"Direct Attack to Space Communication Links","description":"An attacker can leverage communication channels to initially access a resource, using TT&C or a payload channel, opening a communication link to compromise the victim system. An attacker can perform different actions.","url":"https://spaceshield.esa.int/techniques/T2008","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2008 Direct Attack to Space Communication Links","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2002","stixId":"course-of-action--f340a10b-0cc2-4ade-bf9c-5eff01877b3a","name":"Authentication","description":"Authentication permits a secure access to the resource, verifying the actor's identity. It also protects a command or a message from spoofing or modifications. CCSDS SDLS protocol incorporates authentication through MAC. Authentication protects from attacks aiming to access unauthorized resources, to spoof legitimate users, or to manipulate data and communications. (Citation: SRC008) (Citation: SRC017) (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2002"},{"id":"SSH.M2004","stixId":"course-of-action--183b8879-9c10-4d91-b528-efbcac35c570","name":"CCSDS SDLS Sequence numbers","description":"CCSDS SDLS protocol incorporates anti-replay protection through the use of sequence numbers. Increased sequence numbers can also permit the detection of unauthorized messages sent to the Resource. (Citation: SRC008)","url":"https://spaceshield.esa.int/mitigations/M2004"}],"externalReferences":[{"source":"mitre-attack","id":"T2008","url":"https://spaceshield.esa.int/techniques/T2008"}]},{"id":"SSH.T2008.004","stixId":"attack-pattern--e50aac1e-3ff1-4c70-9c25-6cd0f466c5f0","name":"Exploitation of clear mode (also known as safe mode)","description":"An attacker can exploit the TC channel if a spacecraft is in clear mode, e.g., during safe mode of operation. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC003) (Citation: SRC005) (Citation: SRC006) (Citation: SRC008) (Citation: SRC009) (Citation: SRC010)","url":"https://spaceshield.esa.int/techniques/T2008/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2008.004 Exploitation of clear mode (also known as safe mode)","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2008","stixId":"attack-pattern--e35b3790-b1b0-4098-873e-c24818228c32","name":"Direct Attack to Space Communication Links","description":"An attacker can leverage communication channels to initially access a resource, using TT&C or a payload channel, opening a communication link to compromise the victim system. An attacker can perform different actions.","url":"https://spaceshield.esa.int/techniques/T2008"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2008.004","url":"https://spaceshield.esa.int/techniques/T2008/004"},{"source":"SRC005","url":"https://public.ccsds.org/Pubs/231x0b4e0.pdf"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC006","url":"https://public.ccsds.org/Pubs/131x0b4.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2008.006","stixId":"attack-pattern--9f385497-e06d-44c9-91b7-da721010262e","name":"Record and replay TC/TM or mission specific packets","description":"An attacker can record and replay TC/TM packets to deceive the spacecraft or the ground station, causing an unexpected behavior or an erroneous evaluation of the spacecraft status. An attacker can gain access to the data exchanged in a payload channel or even spoof TC. Usually the TM replay doesn't cause an impact, unless timing information are transmitted. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC005) (Citation: SRC009) (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2008/006","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2008.006 Record and replay TC/TM or mission specific packets","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2008","stixId":"attack-pattern--e35b3790-b1b0-4098-873e-c24818228c32","name":"Direct Attack to Space Communication Links","description":"An attacker can leverage communication channels to initially access a resource, using TT&C or a payload channel, opening a communication link to compromise the victim system. An attacker can perform different actions.","url":"https://spaceshield.esa.int/techniques/T2008"}],"mitigations":[{"id":"SSH.M2004","stixId":"course-of-action--183b8879-9c10-4d91-b528-efbcac35c570","name":"CCSDS SDLS Sequence numbers","description":"CCSDS SDLS protocol incorporates anti-replay protection through the use of sequence numbers. Increased sequence numbers can also permit the detection of unauthorized messages sent to the Resource. (Citation: SRC008)","url":"https://spaceshield.esa.int/mitigations/M2004"}],"externalReferences":[{"source":"mitre-attack","id":"T2008.006","url":"https://spaceshield.esa.int/techniques/T2008/006"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC005","url":"https://public.ccsds.org/Pubs/231x0b4e0.pdf"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T2009","stixId":"attack-pattern--aa2f25d9-ed82-403e-af91-f39f23b79c71","name":"Valid Credentials","description":"Adversaries may obtain and abuse credentials to gain Initial Access or Persistence in a space resource. Compromised credentials may be used to bypass access controls placed on systems within the network and to decrypt communication, to send authenticate messages and to take control of the spacecraft. Gained credentials may even be used for persistent access to the resource. \n\nAdversaries may obtain and abuse master or session keys, or target the digital certificates used for the authentication. \n\nStandards: (Citation: SRC014) (Citation: SRC039)","url":"https://spaceshield.esa.int/techniques/T2009","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2009 Valid Credentials","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"},{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2040","stixId":"course-of-action--e88273bc-ed6b-4a33-90f0-849d94335b2a","name":"Secure PKI implementation","description":"Public Key Infrastructure (PKI) is a framework of roles, policies, hardware, software, and procedures necessary to securely create, manage, and use digital certificates and public-key encryption. In spacecraft systems, PKI plays a critical role in securing communications, ensuring that only authorized entities can issue commands or access sensitive data. This is especially important for space-to-ground communication, inter-satellite links, and internal command authentication.\n\nPKI enables strong authentication methods, far more secure than simple passwords, by binding public keys to the identities of spacecraft components, ground stations, or other authorized entities. This process is managed by a Certificate Authority (CA), which issues and manages digital certificates that verify identities and ensure the integrity of data transfers.\n\nPKI for spacecraft typically involves the secure registration, issuance, and management of certificates. ","url":"https://spaceshield.esa.int/mitigations/M2040"},{"id":"SSH.M2060","stixId":"course-of-action--dbc85852-b7bf-43e7-94ee-9fb6d459164b","name":"Establish processes, procedures, and security measures to protect cryptographic keys / key management","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2060"},{"id":"SSH.M2006","stixId":"course-of-action--895b347b-1dd5-4377-b079-72aa607b4506","name":"Protect OTAR Key Management Service","description":"Over-the-air rekeying (OTAR) is the process of updating encryption keys via an existing encrypted communication channel.\t\nCCSDS Recommended Practice provides specific means for protection of the OTAR key management service. All key management communication must be protected by a security protocol such as the Space Data-Link Layer Security Protocol. (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/mitigations/M2006"}],"externalReferences":[{"source":"mitre-attack","id":"T2009","url":"https://spaceshield.esa.int/techniques/T2009"},{"source":"SRC039","url":"https://public.ccsds.org/Pubs/352x0b2.pdf"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"}]},{"id":"SSH.T2009.001","stixId":"attack-pattern--4a3b3f58-a61c-440c-a690-797e15d8ba56","name":"Steal cryptographic keys","description":"Adversaries may obtain and abuse master or session keys to gain Initial Access or Persistence. Compromised credentials may be used to bypass access controls placed on various resources on systems within the network and may even be used for persistent access to communication channels. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2009/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2009.001 Steal cryptographic keys","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"},{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2009","stixId":"attack-pattern--aa2f25d9-ed82-403e-af91-f39f23b79c71","name":"Valid Credentials","description":"Adversaries may obtain and abuse credentials to gain Initial Access or Persistence in a space resource. Compromised credentials may be used to bypass access controls placed on systems within the network and to decrypt communication, to send authenticate messages and to take control of the spacecraft. Gained credentials may even be used for persistent access to the resource. \n\nAdversaries may obtain and abuse master or session keys, or target the digital certificates used for the authentication. \n\nStandards: (Citation: SRC014) (Citation: SRC039)","url":"https://spaceshield.esa.int/techniques/T2009"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2009.001","url":"https://spaceshield.esa.int/techniques/T2009/001"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2009.002","stixId":"attack-pattern--b0a1f667-9054-4585-b65c-ead2de68eb9c","name":"Forge Digital Certificates","description":"If an attacker gains control of the credential-management system and issues credentials, he can access the system and maintain a persistent control on it. There is a need to invalidate existing credentials and reissue all credentials. CCSDS recommends two forms of credentials: X.509 certificates and protected simple authentication. The authenticity of an X.509 certificate is dependent upon the digital signature of the CA attesting to the credential. If the digital signature algorithm used by the CA is of insufficient cryptographic strength, a credential may be spoofed. (Citation: MITRE ATT&CK)\n\nStandard/references: (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2009/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2009.002 Forge Digital Certificates","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"},{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2009","stixId":"attack-pattern--aa2f25d9-ed82-403e-af91-f39f23b79c71","name":"Valid Credentials","description":"Adversaries may obtain and abuse credentials to gain Initial Access or Persistence in a space resource. Compromised credentials may be used to bypass access controls placed on systems within the network and to decrypt communication, to send authenticate messages and to take control of the spacecraft. Gained credentials may even be used for persistent access to the resource. \n\nAdversaries may obtain and abuse master or session keys, or target the digital certificates used for the authentication. \n\nStandards: (Citation: SRC014) (Citation: SRC039)","url":"https://spaceshield.esa.int/techniques/T2009"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2009.002","url":"https://spaceshield.esa.int/techniques/T2009/002"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2009.003","stixId":"attack-pattern--e6cafff7-c76a-4195-aacf-9cd605a0f9e0","name":"Brute force attack against TC channel or mission channel","description":"An attacker can use brute force to gain access to a TC channel, to force encryption or to guess the valid commands.","url":"https://spaceshield.esa.int/techniques/T2009/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2009.003 Brute force attack against TC channel or mission channel","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2009","stixId":"attack-pattern--aa2f25d9-ed82-403e-af91-f39f23b79c71","name":"Valid Credentials","description":"Adversaries may obtain and abuse credentials to gain Initial Access or Persistence in a space resource. Compromised credentials may be used to bypass access controls placed on systems within the network and to decrypt communication, to send authenticate messages and to take control of the spacecraft. Gained credentials may even be used for persistent access to the resource. \n\nAdversaries may obtain and abuse master or session keys, or target the digital certificates used for the authentication. \n\nStandards: (Citation: SRC014) (Citation: SRC039)","url":"https://spaceshield.esa.int/techniques/T2009"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2009.003","url":"https://spaceshield.esa.int/techniques/T2009/003"}]},{"id":"SSH.T2010","stixId":"attack-pattern--12be69d9-29f5-4d24-9f32-d956d9c997fe","name":"Modification of On Board Control Procedures modification","description":"An On-Board Control Procedure (OBCP) is a software program designed to be executed by an OBCP engine, which can be loaded, executed, and also replaced, on-board the spacecraft. An attacker can attempt to modify them to execute her own commands and control the spacecraft.\nThe attacker can attempt to modify OBCP to gain access to the interface of the On-Board Computer (OBC) and interact with it. In New Space mission, and in general missions using CubeSats, Execution can include exploitation of Micropython flaws or vulnerabilities or using Shell commands for various purposes (further reconnaissance, privilege escalation, launching attacks like Denial of Service, take full control of spacecraft, etc.).\n\n\nStandard/references: (Citation: SRC023)","url":"https://spaceshield.esa.int/techniques/T2010","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2010 Modification of On Board Control Procedures modification","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0002","name":"Execution","shortname":"execution"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2055","stixId":"course-of-action--8ef71552-a4e7-4884-9de0-1e6d75ed21a5","name":"Operating Systems partitioning","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2055"},{"id":"SSH.M2052","stixId":"course-of-action--a42b1a56-0c96-4d1e-8533-54c52b158dbe","name":"Software segregation / isolation","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2052"},{"id":"SSH.M2051","stixId":"course-of-action--fd49f61e-39fa-4269-a85c-b79d51857f46","name":"On Board Authentication for executing critical commands","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2051"},{"id":"SSH.M2019","stixId":"course-of-action--14df2304-0f7c-43d8-8b4a-41d1747a2123","name":"Data integrity schemes","description":"Use data integrity schemes to protect data from unauthorized modifications, or from unintentional corruptions due to noise or storage defects (hashing, check values, digital signatures). SDLS provides integrity protection on the transmitted data, with the computation of a MAC. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2019"},{"id":"SSH.M2054","stixId":"course-of-action--ad3755c3-8e19-40b9-9c5a-235626d86594","name":"Implementation on Trusted Execution Environments for critical parts of procedures","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2054"},{"id":"SSH.M2053","stixId":"course-of-action--8a215305-a16e-43de-a150-8f6bc65e8a44","name":"Role Based Access Control","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2053"}],"externalReferences":[{"source":"mitre-attack","id":"T2010","url":"https://spaceshield.esa.int/techniques/T2010"},{"source":"SRC023","url":"https://ecss.nl/standard/ecss-e-st-70-01c-on-board-control-procedures/"}]},{"id":"SSH.T2012","stixId":"attack-pattern--7eb45e37-e8f9-4aaf-83f7-6c43b9b8c280","name":"Payload Exploitation to Execute Commands","description":"If an attacker gains access to payload, he can execute telecommands; in addition, he can propagate the attack exploiting payload activities. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2012","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2012 Payload Exploitation to Execute Commands","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0002","name":"Execution","shortname":"execution"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2051","stixId":"course-of-action--fd49f61e-39fa-4269-a85c-b79d51857f46","name":"On Board Authentication for executing critical commands","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2051"},{"id":"SSH.M2057","stixId":"course-of-action--750082f5-48a4-470f-87a8-974a30131d26","name":"Payload specific countermeasures","description":"Implement tailored security mechanisms and protocols to address vulnerabilities unique to the spacecraft payload. These could include encryption for payload data, tamper-resistant hardware, and specific anomaly detection systems to monitor payload operations and communication.","url":"https://attack.mitre.org/mitigations/M2057"},{"id":"SSH.M2056","stixId":"course-of-action--d4f15257-3627-4239-8afd-d8064294cbf4","name":"Platform protection","description":"using logical and/or physical protection segregation mechanisms from payload","url":"https://spaceshield.esa.int/mitigations/M2056"}],"externalReferences":[{"source":"mitre-attack","id":"T2012","url":"https://spaceshield.esa.int/techniques/T2012"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2013","stixId":"attack-pattern--eb56e997-05f4-40a9-9fe1-e6978a2c5093","name":"Key Management Infrastructure Manipulation","description":"Key infrastructures provide the technical means for managing the key life cycles as well as for the distribution of keys using security protocols or other means. If an attacker manipulates them, he can gain and maintain an authorized access to the protected resource. Encryption keys used to encrypt TM/TC can be replaced in order to gain permanent access to other functionalities, or to temporarily interrupt the owner's control.\n\nStandard/references: (Citation: SRC014) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2013","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2013 Key Management Infrastructure Manipulation","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2060","stixId":"course-of-action--dbc85852-b7bf-43e7-94ee-9fb6d459164b","name":"Establish processes, procedures, and security measures to protect cryptographic keys / key management","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2060"},{"id":"SSH.M2059","stixId":"course-of-action--dd0b4b05-1b76-4461-8c17-5054fce6f2ac","name":"Physical and network protection of key management systems","description":"using border protection devices like diodes, etc.","url":"https://spaceshield.esa.int/mitigations/M2059"},{"id":"SSH.M2058","stixId":"course-of-action--0401ceb6-951c-44e3-af34-3b1a7c9b8519","name":"Physical protection and isolation of root keys","description":"Implement robust physical security measures to protect and isolate root cryptographic keys. This includes secure hardware modules, tamper-evident seals, and physical segregation within spacecraft or ground facilities to ensure that keys remain secure during storage, generation, and use.","url":"https://attack.mitre.org/mitigations/M2058"}],"externalReferences":[{"source":"mitre-attack","id":"T2013","url":"https://spaceshield.esa.int/techniques/T2013"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"}]},{"id":"SSH.T2013.001","stixId":"attack-pattern--8b7d96e7-84a0-48b2-aad2-5be8e5c0645e","name":"Replace / generate new Session Keys","description":"Adversaries can replace or generate encryption keys used to encrypt TM/TC in order to gain permanent access to other functionalities. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC014) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2013/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2013.001 Replace / generate new Session Keys","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2013","stixId":"attack-pattern--eb56e997-05f4-40a9-9fe1-e6978a2c5093","name":"Key Management Infrastructure Manipulation","description":"Key infrastructures provide the technical means for managing the key life cycles as well as for the distribution of keys using security protocols or other means. If an attacker manipulates them, he can gain and maintain an authorized access to the protected resource. Encryption keys used to encrypt TM/TC can be replaced in order to gain permanent access to other functionalities, or to temporarily interrupt the owner's control.\n\nStandard/references: (Citation: SRC014) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2013"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2013.001","url":"https://spaceshield.esa.int/techniques/T2013/001"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2013.002","stixId":"attack-pattern--a26a088a-b91a-46e8-a852-bdef77dfc0ae","name":"Replace / generate new Master Keys","description":"Adversaries can replace the master key used to encrypt TM/TC in order to gain permanent access to other functionalities, or interrupt the owner's control by generating new ones.","url":"https://spaceshield.esa.int/techniques/T2013/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2013.002 Replace / generate new Master Keys","platforms":["None"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2013","stixId":"attack-pattern--eb56e997-05f4-40a9-9fe1-e6978a2c5093","name":"Key Management Infrastructure Manipulation","description":"Key infrastructures provide the technical means for managing the key life cycles as well as for the distribution of keys using security protocols or other means. If an attacker manipulates them, he can gain and maintain an authorized access to the protected resource. Encryption keys used to encrypt TM/TC can be replaced in order to gain permanent access to other functionalities, or to temporarily interrupt the owner's control.\n\nStandard/references: (Citation: SRC014) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2013"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2013.002","url":"https://spaceshield.esa.int/techniques/T2013/002"}]},{"id":"SSH.T2014","stixId":"attack-pattern--50532d5f-9620-453e-915d-91dd38d2441c","name":"Backdoor Installation","description":"An attacker can interfere with the hardware or the software, integrating or modifying the existing software, hardware configuration or the transponder configuration to permit himself a future access to the resource.\t\n\nThe attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system.\nReplacement of a product in the supply chain with a custom or counterfeit part can be performed to damage the system or to use it as a future backdoor.\nAn attacker can also modify the OBSW to permit a future access on the resource with a software backdoor.\nAn attacker can also modify the payload hardware, software, or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2014 Backdoor Installation","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2019","stixId":"course-of-action--14df2304-0f7c-43d8-8b4a-41d1747a2123","name":"Data integrity schemes","description":"Use data integrity schemes to protect data from unauthorized modifications, or from unintentional corruptions due to noise or storage defects (hashing, check values, digital signatures). SDLS provides integrity protection on the transmitted data, with the computation of a MAC. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2019"},{"id":"SSH.M2062","stixId":"course-of-action--2df73ed7-53d2-40f3-bc2e-8889fb474cc7","name":"Recovery to a known good state","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2062"},{"id":"SSH.M2061","stixId":"course-of-action--a109e637-d2db-4b92-96da-d8105946acf7","name":"Remote attestation","description":"Employ remote attestation mechanisms to validate the integrity of spacecraft software or firmware remotely. This process enables ground control to verify that the onboard systems are unmodified and secure, ensuring confidence in the operation of the spacecraft and communication links.","url":"https://attack.mitre.org/mitigations/M2061"}],"externalReferences":[{"source":"mitre-attack","id":"T2014","url":"https://spaceshield.esa.int/techniques/T2014"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2014.001","stixId":"attack-pattern--6b167b58-02f7-4624-b47c-cc3343a701c1","name":"Hardcoded credentials and/or keys","description":"The attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2014.001 Hardcoded credentials and/or keys","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2014","stixId":"attack-pattern--50532d5f-9620-453e-915d-91dd38d2441c","name":"Backdoor Installation","description":"An attacker can interfere with the hardware or the software, integrating or modifying the existing software, hardware configuration or the transponder configuration to permit himself a future access to the resource.\t\n\nThe attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system.\nReplacement of a product in the supply chain with a custom or counterfeit part can be performed to damage the system or to use it as a future backdoor.\nAn attacker can also modify the OBSW to permit a future access on the resource with a software backdoor.\nAn attacker can also modify the payload hardware, software, or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2014.001","url":"https://spaceshield.esa.int/techniques/T2014/001"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2014.002","stixId":"attack-pattern--8fd95b6b-2d2c-4460-8daf-122c071d8186","name":"Integration of custom malicious hardware","description":"Replacement of a product in the supply chain with a custom or counterfeit part to damage the system or to use it as a future backdoor. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2014.002 Integration of custom malicious hardware","platforms":["None"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2014","stixId":"attack-pattern--50532d5f-9620-453e-915d-91dd38d2441c","name":"Backdoor Installation","description":"An attacker can interfere with the hardware or the software, integrating or modifying the existing software, hardware configuration or the transponder configuration to permit himself a future access to the resource.\t\n\nThe attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system.\nReplacement of a product in the supply chain with a custom or counterfeit part can be performed to damage the system or to use it as a future backdoor.\nAn attacker can also modify the OBSW to permit a future access on the resource with a software backdoor.\nAn attacker can also modify the payload hardware, software, or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2014.002","url":"https://spaceshield.esa.int/techniques/T2014/002"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2014.003","stixId":"attack-pattern--c0ed5e56-f7fc-4e6d-ba92-eecb856948a7","name":"OBSW modification","description":"An attacker can modify the OBSW to permit a future access on the resource with a software backdoor. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2014.003 OBSW modification","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2014","stixId":"attack-pattern--50532d5f-9620-453e-915d-91dd38d2441c","name":"Backdoor Installation","description":"An attacker can interfere with the hardware or the software, integrating or modifying the existing software, hardware configuration or the transponder configuration to permit himself a future access to the resource.\t\n\nThe attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system.\nReplacement of a product in the supply chain with a custom or counterfeit part can be performed to damage the system or to use it as a future backdoor.\nAn attacker can also modify the OBSW to permit a future access on the resource with a software backdoor.\nAn attacker can also modify the payload hardware, software, or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2014.003","url":"https://spaceshield.esa.int/techniques/T2014/003"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2014.004","stixId":"attack-pattern--5147e22e-108c-4159-890f-4783799aa03c","name":"Transponder reconfiguration","description":"An attacker can change the transponder configuration to permit a future radio access on the resource. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2014.004 Transponder reconfiguration","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2014","stixId":"attack-pattern--50532d5f-9620-453e-915d-91dd38d2441c","name":"Backdoor Installation","description":"An attacker can interfere with the hardware or the software, integrating or modifying the existing software, hardware configuration or the transponder configuration to permit himself a future access to the resource.\t\n\nThe attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system.\nReplacement of a product in the supply chain with a custom or counterfeit part can be performed to damage the system or to use it as a future backdoor.\nAn attacker can also modify the OBSW to permit a future access on the resource with a software backdoor.\nAn attacker can also modify the payload hardware, software, or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2014.004","url":"https://spaceshield.esa.int/techniques/T2014/004"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2014.005","stixId":"attack-pattern--b221dd3f-da51-4009-bc3e-55e24fce57eb","name":"Payload modification","description":"An attacker can also modify the payload hardware, software or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2014.005 Payload modification","platforms":["Space Segment","Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0003","name":"Persistence","shortname":"persistence"}],"parentTechniques":[{"id":"SSH.T2014","stixId":"attack-pattern--50532d5f-9620-453e-915d-91dd38d2441c","name":"Backdoor Installation","description":"An attacker can interfere with the hardware or the software, integrating or modifying the existing software, hardware configuration or the transponder configuration to permit himself a future access to the resource.\t\n\nThe attacker can hardcode credentials during the supply chain phase with custom, to have a secure access to the resource if the component is integrated in the system.\nReplacement of a product in the supply chain with a custom or counterfeit part can be performed to damage the system or to use it as a future backdoor.\nAn attacker can also modify the OBSW to permit a future access on the resource with a software backdoor.\nAn attacker can also modify the payload hardware, software, or configuration to create a future access on the payload itself, either to target it or to use it against the whole resource.\n (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2014"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2014.005","url":"https://spaceshield.esa.int/techniques/T2014/005"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2015","stixId":"attack-pattern--8eb9e6dd-ec49-4c9b-9fe5-c3bce7f97f60","name":"Retrieve TT&C master/session keys","description":"The attacker gains knowledge of a Session or Master Key. In general, there isn't immediate way to uncover this corruption, until it is used to modify the system's behaviour. In case of a suspicious key corruption, the key replacement shall be executed as soon as possible. (Citation: SRC014) (Citation: SRC025)\n\nStandard/references: (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/techniques/T2015","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2015 Retrieve TT&C master/session keys","platforms":["Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2073","stixId":"course-of-action--b80d6bbb-b418-4de8-90ca-10a1cbdf4298","name":"Revoke keys and replace with new ones (including master keys, if needed)","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2073"},{"id":"SSH.M2074","stixId":"course-of-action--fe322eb3-1189-4ce6-b764-52b87d97437f","name":"Protect/isolate Key Mangement Facility","description":"Secure and isolate key management facilities to prevent unauthorized access or tampering with cryptographic keys. This involves employing physical security controls (e.g., restricted areas, surveillance), logical access controls, and network segmentation to ensure that key generation, storage, and distribution processes remain uncompromised.","url":"https://attack.mitre.org/mitigations/M2074"}],"externalReferences":[{"source":"mitre-attack","id":"T2015","url":"https://spaceshield.esa.int/techniques/T2015"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"}]},{"id":"SSH.T2015.001","stixId":"attack-pattern--bd0ddb55-2666-4669-9ae4-a563e3da3925","name":"Compromise of Key Management Facility","description":"An attacker can gain control of the credential-management system and can issue credentials. This is a high risk for CCSDS systems using credentials, with the need to invalidate existing credentials and reissue all credentials.","url":"https://spaceshield.esa.int/techniques/T2015/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2015.001 Compromise of Key Management Facility","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[{"id":"SSH.T2015","stixId":"attack-pattern--8eb9e6dd-ec49-4c9b-9fe5-c3bce7f97f60","name":"Retrieve TT&C master/session keys","description":"The attacker gains knowledge of a Session or Master Key. In general, there isn't immediate way to uncover this corruption, until it is used to modify the system's behaviour. In case of a suspicious key corruption, the key replacement shall be executed as soon as possible. (Citation: SRC014) (Citation: SRC025)\n\nStandard/references: (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/techniques/T2015"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2015.001","url":"https://spaceshield.esa.int/techniques/T2015/001"}]},{"id":"SSH.T2015.002","stixId":"attack-pattern--315d6e1d-6a55-4a76-a9ba-ccd843f2fa32","name":"Cryptographic Key Corruption","description":"The attacker can gain knowledge of a Session or Master Key corrupting the cryptographic algorithm. (Citation: SRC014)\n\nStandard/references: (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/techniques/T2015/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2015.002 Cryptographic Key Corruption","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[{"id":"SSH.T2015","stixId":"attack-pattern--8eb9e6dd-ec49-4c9b-9fe5-c3bce7f97f60","name":"Retrieve TT&C master/session keys","description":"The attacker gains knowledge of a Session or Master Key. In general, there isn't immediate way to uncover this corruption, until it is used to modify the system's behaviour. In case of a suspicious key corruption, the key replacement shall be executed as soon as possible. (Citation: SRC014) (Citation: SRC025)\n\nStandard/references: (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/techniques/T2015"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2015.002","url":"https://spaceshield.esa.int/techniques/T2015/002"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"}]},{"id":"SSH.T2015.003","stixId":"attack-pattern--9ed5381a-2486-465b-9380-2f99bee071d1","name":"Interception of Key Management Communication","description":"The attacker can intercept messages that are being transmitted as part of the Key Management Services with the intention either to obtain knowledge of a specific key or to interfere with the Key Management Service. (Citation: SRC025)\n\nStandard/references: (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/techniques/T2015/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2015.003 Interception of Key Management Communication","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[{"id":"SSH.T2015","stixId":"attack-pattern--8eb9e6dd-ec49-4c9b-9fe5-c3bce7f97f60","name":"Retrieve TT&C master/session keys","description":"The attacker gains knowledge of a Session or Master Key. In general, there isn't immediate way to uncover this corruption, until it is used to modify the system's behaviour. In case of a suspicious key corruption, the key replacement shall be executed as soon as possible. (Citation: SRC014) (Citation: SRC025)\n\nStandard/references: (Citation: SRC014) (Citation: SRC025)","url":"https://spaceshield.esa.int/techniques/T2015"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2015.003","url":"https://spaceshield.esa.int/techniques/T2015/003"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"}]},{"id":"SSH.T2016","stixId":"attack-pattern--092baf9c-4161-4c83-8071-c731815c40b6","name":"Lateral Movement via common Avionics Bus","description":"This attack is performed against a part of the system via a physical bus shared with a compromised system. Unprotected bus can be used to extend an attack to uncompromised components. In example, if payload has access to main 1553 bus, a hosted payload attack is possible. Fault injection or Adversary-in-the-Middle (AiTM) can be done into the 1553 bus.","url":"https://spaceshield.esa.int/techniques/T2016","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2016 Lateral Movement via common Avionics Bus","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0008","name":"Lateral Movement","shortname":"lateral-movement"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2007","stixId":"course-of-action--f24de305-389d-40c0-a78f-77d19f3f5dc6","name":"Partitioning/Separation","description":"Time and Space Partitioning or other satellite hypervisor types should protect systems from mutual interferences, creating security borders between services and preventing unauthorized interactions. (Citation: SRC015)","url":"https://spaceshield.esa.int/mitigations/M2007"}],"externalReferences":[{"source":"mitre-attack","id":"T2016","url":"https://spaceshield.esa.int/techniques/T2016"}]},{"id":"SSH.T2017","stixId":"attack-pattern--249c2edd-2be8-43f9-a879-cdf9cc38f1e3","name":"Compromise of another partition in Time and Space Partitioning OS or other types of satellite hypervisors","description":"If a partitition is compromised, access to a critical partition can be gained through ports allowed by hypervisor. Information security is usually configured at the application level, with the execution confined to the application's partition and controlled communication with the remaining partitions. Time and Space Partitioning or other satellite hypervisor types should protect system from interferences. All communication passes through the security components, which can include monitoring and cryptographic mechanisms.\n\nStandard/references: (Citation: SRC015)","url":"https://spaceshield.esa.int/techniques/T2017","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2017 Compromise of another partition in Time and Space Partitioning OS or other types of satellite hypervisors","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0008","name":"Lateral Movement","shortname":"lateral-movement"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2007","stixId":"course-of-action--f24de305-389d-40c0-a78f-77d19f3f5dc6","name":"Partitioning/Separation","description":"Time and Space Partitioning or other satellite hypervisor types should protect systems from mutual interferences, creating security borders between services and preventing unauthorized interactions. (Citation: SRC015)","url":"https://spaceshield.esa.int/mitigations/M2007"}],"externalReferences":[{"source":"mitre-attack","id":"T2017","url":"https://spaceshield.esa.int/techniques/T2017"},{"source":"SRC015","url":"https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=5226855"}]},{"id":"SSH.T2018","stixId":"attack-pattern--293477cc-9c5e-4a87-87cc-cbe385134444","name":"Data from link eavesdropping","description":"Adversaries can collect data transmitted over a channel, if he is able to decode and decrypt the communication. (Citation: SRC017) (Citation: South-West of France)\n\nAn attacker can collect and have access to data transmitted by TT&C if the communication doesn't rely on encryption. CCSDS SDLS protocol incorporates confidentiality services through encryption of the frame data, that can be used as a mitigation.\nAdversaries can collect data transmitted over the payload channel if it is used.\n","url":"https://spaceshield.esa.int/techniques/T2018","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2018 Data from link eavesdropping","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2068","stixId":"course-of-action--b2a3c805-447c-40d3-b0dc-59d2250c7458","name":"Authenticated encryption","description":"Authenticated encryption is a cryptographic technique that ensures both the confidentiality and authenticity of data. Authenticated encryption is crucial in preventing adversaries from intercepting and manipulating data, as it secures communication against both unauthorized access and tampering.\n\nThis method ensures that even if an adversary intercepts the data, they cannot decrypt it or alter its integrity without detection.\n\nImplementing protocols such as the CCSDS SDLS, which incorporates encryption, authentication, and authenticated encryption is essential for protecting space-link communications.","url":"https://attack.mitre.org/mitigations/M2068"}],"externalReferences":[{"source":"mitre-attack","id":"T2018","url":"https://spaceshield.esa.int/techniques/T2018"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"South-West of France","url":"https://www.intelligenceonline.fr/asie-pacifique/2025/06/11/pres-de-toulouse-les-grandes-oreilles-chinoises-soupconnees-d-espionner-les-satellites-francais,110462871-eve"}]},{"id":"SSH.T2018.001","stixId":"attack-pattern--b1eda5e4-4efe-4925-834e-9f890c97d317","name":"Payload eavesdropping","description":"Adversaries can collect data transmitted over the payload channel, if it is used. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003)","url":"https://spaceshield.esa.int/techniques/T2018/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2018.001 Payload eavesdropping","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[{"id":"SSH.T2018","stixId":"attack-pattern--293477cc-9c5e-4a87-87cc-cbe385134444","name":"Data from link eavesdropping","description":"Adversaries can collect data transmitted over a channel, if he is able to decode and decrypt the communication. (Citation: SRC017) (Citation: South-West of France)\n\nAn attacker can collect and have access to data transmitted by TT&C if the communication doesn't rely on encryption. CCSDS SDLS protocol incorporates confidentiality services through encryption of the frame data, that can be used as a mitigation.\nAdversaries can collect data transmitted over the payload channel if it is used.\n","url":"https://spaceshield.esa.int/techniques/T2018"}],"mitigations":[{"id":"SSH.M2003","stixId":"course-of-action--d87c5194-1a09-4d5e-a8f8-5fb53a5e26b9","name":"Encryption of communications","description":"Encryption of communications  hides the message content to unauthorized eavesdropper, ensuring confidentiality. \n\nThe Space Data Link Security Protocol is a standard defined how to apply encryption, authenticated encryption and encryption only (not recommended) for the CCSDS communication at the Data Link Layer.\n\nPayload traffic, if related to network communications, can use specific traffic protocols, e.g., QPEP. Range data shall be also encrypted. (Citation: SRC008) (Citation: SRC017) (Citation: SRC029)","url":"https://spaceshield.esa.int/mitigations/M2003"}],"externalReferences":[{"source":"mitre-attack","id":"T2018.001","url":"https://spaceshield.esa.int/techniques/T2018/001"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T2018.002","stixId":"attack-pattern--c1173e48-4e32-4cfe-bf08-197b26afe2e0","name":"Range Data eavesdropping","description":"Adversaries can intercept range data to locate and more accurately target the victim spacecraft. Mitigation from higher level protocols (encryption to assure confidentiality). (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC008) (Citation: SRC021)","url":"https://spaceshield.esa.int/techniques/T2018/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2018.002 Range Data eavesdropping","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[{"id":"SSH.T2018","stixId":"attack-pattern--293477cc-9c5e-4a87-87cc-cbe385134444","name":"Data from link eavesdropping","description":"Adversaries can collect data transmitted over a channel, if he is able to decode and decrypt the communication. (Citation: SRC017) (Citation: South-West of France)\n\nAn attacker can collect and have access to data transmitted by TT&C if the communication doesn't rely on encryption. CCSDS SDLS protocol incorporates confidentiality services through encryption of the frame data, that can be used as a mitigation.\nAdversaries can collect data transmitted over the payload channel if it is used.\n","url":"https://spaceshield.esa.int/techniques/T2018"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2018.002","url":"https://spaceshield.esa.int/techniques/T2018/002"},{"source":"SRC021","url":"https://public.ccsds.org/Pubs/415x1b1.pdf"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"}]},{"id":"SSH.T2018.003","stixId":"attack-pattern--d474cc34-ad6e-4529-b882-9828aef2c546","name":"TC/TM eavesdropping","description":"An attacker can collect and have access to data transmitted by TT&C if the communication doesn't rely on encryption. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC008) (Citation: SRC009) (Citation: SRC010)","url":"https://spaceshield.esa.int/techniques/T2018/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2018.003 TC/TM eavesdropping","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0009","name":"Collection","shortname":"collection"}],"parentTechniques":[{"id":"SSH.T2018","stixId":"attack-pattern--293477cc-9c5e-4a87-87cc-cbe385134444","name":"Data from link eavesdropping","description":"Adversaries can collect data transmitted over a channel, if he is able to decode and decrypt the communication. (Citation: SRC017) (Citation: South-West of France)\n\nAn attacker can collect and have access to data transmitted by TT&C if the communication doesn't rely on encryption. CCSDS SDLS protocol incorporates confidentiality services through encryption of the frame data, that can be used as a mitigation.\nAdversaries can collect data transmitted over the payload channel if it is used.\n","url":"https://spaceshield.esa.int/techniques/T2018"}],"mitigations":[{"id":"SSH.M2003","stixId":"course-of-action--d87c5194-1a09-4d5e-a8f8-5fb53a5e26b9","name":"Encryption of communications","description":"Encryption of communications  hides the message content to unauthorized eavesdropper, ensuring confidentiality. \n\nThe Space Data Link Security Protocol is a standard defined how to apply encryption, authenticated encryption and encryption only (not recommended) for the CCSDS communication at the Data Link Layer.\n\nPayload traffic, if related to network communications, can use specific traffic protocols, e.g., QPEP. Range data shall be also encrypted. (Citation: SRC008) (Citation: SRC017) (Citation: SRC029)","url":"https://spaceshield.esa.int/mitigations/M2003"}],"externalReferences":[{"source":"mitre-attack","id":"T2018.003","url":"https://spaceshield.esa.int/techniques/T2018/003"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"}]},{"id":"SSH.T2019","stixId":"attack-pattern--eb04ee28-2f75-4d64-a5a4-178d2f4c37b9","name":"Telecommand a Spacecraft","description":"Command and Control consists of techniques that adversaries may use to communicate with systems under their control. Adversaries commonly attempt to mimic normal, expected traffic to avoid detection  (Citation: MITRE ATT&CK).\nIf the attacker has the system under its control, he can interact with it to command it\n\nStandard/references: (Citation: SRC003) (Citation: SRC009) (Citation: Cyberattack targeting Landsat-7 and Terra EOS)","url":"https://spaceshield.esa.int/techniques/T2019","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2019 Telecommand a Spacecraft","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0011","name":"Command and Control","shortname":"command-and-control"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2046","stixId":"course-of-action--1dd33aed-a48d-46ca-89a5-ee8e2726612e","name":"Anti-replay protection mechanisms","description":"Implement anti-replay protection mechanisms to prevent adversaries from intercepting and reusing previously transmitted messages. In the context of space systems, this involves using techniques like sequence numbers, timestamps, and unique message identifiers to ensure that every communication (such as telemetry, tracking, and command data) is valid and unique. ","url":"https://attack.mitre.org/mitigations/M2046"},{"id":"SSH.M2070","stixId":"course-of-action--bcbc6109-d973-4e21-a3ed-72fa45151a40","name":"Internal segregation and /or authentication","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2070"},{"id":"SSH.M2069","stixId":"course-of-action--fe50f2bc-a217-4d22-9cf2-83b0e4c811d7","name":"Strong authentication of Telecommands","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2069"}],"externalReferences":[{"source":"mitre-attack","id":"T2019","url":"https://spaceshield.esa.int/techniques/T2019"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"},{"source":"Cyberattack targeting Landsat-7 and Terra EOS","url":"https://www.uscc.gov/sites/default/files/annual_reports/annual_report_full_11.pdf"}]},{"id":"SSH.T2019.004","stixId":"attack-pattern--5058fd05-7255-402c-a81e-f68c7b3d2a03","name":"Telecommand within a spacecraft","description":"From inside the spacecraft (after gaining access eg to a payload), an attacker can send telecommand to the on board computer.","url":"https://attack.mitre.org/techniques/T2019/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2019.004 Telecommand within a spacecraft","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0011","name":"Command and Control","shortname":"command-and-control"}],"parentTechniques":[{"id":"SSH.T2019","stixId":"attack-pattern--eb04ee28-2f75-4d64-a5a4-178d2f4c37b9","name":"Telecommand a Spacecraft","description":"Command and Control consists of techniques that adversaries may use to communicate with systems under their control. Adversaries commonly attempt to mimic normal, expected traffic to avoid detection  (Citation: MITRE ATT&CK).\nIf the attacker has the system under its control, he can interact with it to command it\n\nStandard/references: (Citation: SRC003) (Citation: SRC009) (Citation: Cyberattack targeting Landsat-7 and Terra EOS)","url":"https://spaceshield.esa.int/techniques/T2019"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2019.004","url":"https://attack.mitre.org/techniques/T2019/004"}]},{"id":"SSH.T2019.005","stixId":"attack-pattern--16d2a8af-e2e2-45a5-938f-64fd99bb71d4","name":"Replay attacks","description":"An attacker can intercept a message (e.g with jamming) stored it , and then replayed it.","url":"https://spaceshield.esa.int/techniques/T2019/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2019.005 Replay attacks","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0011","name":"Command and Control","shortname":"command-and-control"}],"parentTechniques":[{"id":"SSH.T2019","stixId":"attack-pattern--eb04ee28-2f75-4d64-a5a4-178d2f4c37b9","name":"Telecommand a Spacecraft","description":"Command and Control consists of techniques that adversaries may use to communicate with systems under their control. Adversaries commonly attempt to mimic normal, expected traffic to avoid detection  (Citation: MITRE ATT&CK).\nIf the attacker has the system under its control, he can interact with it to command it\n\nStandard/references: (Citation: SRC003) (Citation: SRC009) (Citation: Cyberattack targeting Landsat-7 and Terra EOS)","url":"https://spaceshield.esa.int/techniques/T2019"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2019.005","url":"https://spaceshield.esa.int/techniques/T2019/005"}]},{"id":"SSH.T2019.006","stixId":"attack-pattern--4cb74844-1077-4e78-a51e-d61606b92d58","name":"Telecommand capabilties","description":"An attacker can send command with a direct access after obtaining telecommand capabilities ( e.g by hijacking a ground station).","url":"https://spaceshield.esa.int/techniques/T2019/006","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2019.006 Telecommand capabilties","platforms":["Space-link communication","Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0011","name":"Command and Control","shortname":"command-and-control"}],"parentTechniques":[{"id":"SSH.T2019","stixId":"attack-pattern--eb04ee28-2f75-4d64-a5a4-178d2f4c37b9","name":"Telecommand a Spacecraft","description":"Command and Control consists of techniques that adversaries may use to communicate with systems under their control. Adversaries commonly attempt to mimic normal, expected traffic to avoid detection  (Citation: MITRE ATT&CK).\nIf the attacker has the system under its control, he can interact with it to command it\n\nStandard/references: (Citation: SRC003) (Citation: SRC009) (Citation: Cyberattack targeting Landsat-7 and Terra EOS)","url":"https://spaceshield.esa.int/techniques/T2019"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2019.006","url":"https://spaceshield.esa.int/techniques/T2019/006"}]},{"id":"SSH.T2021","stixId":"attack-pattern--f78623fa-f03d-45d7-8dae-49da4b93c86d","name":"Exfiltration Over Payload Channel","description":"Malicious software can send data through the Payload channel (if implemented). (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC006) (Citation: SRC010)","url":"https://spaceshield.esa.int/techniques/T2021","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2021 Exfiltration Over Payload Channel","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0010","name":"Exfiltration","shortname":"exfiltration"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2021","url":"https://spaceshield.esa.int/techniques/T2021"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC006","url":"https://public.ccsds.org/Pubs/131x0b4.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2022","stixId":"attack-pattern--affb661a-8559-4f33-b75f-753d181f1bfd","name":"Exfiltration Over TM Channel","description":"Malicious software can send data through the TM channel (usually the only connection channel available). (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC006) (Citation: SRC010)","url":"https://spaceshield.esa.int/techniques/T2022","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2022 Exfiltration Over TM Channel","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0010","name":"Exfiltration","shortname":"exfiltration"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2022","url":"https://spaceshield.esa.int/techniques/T2022"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC006","url":"https://public.ccsds.org/Pubs/131x0b4.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2024","stixId":"attack-pattern--bec77139-cea1-42d1-b6d7-8a16873bd078","name":"Transmitted Data Manipulation","description":"An attacker can modify transmitted data, jamming or overpowering the original signal and retransmitting a modified copy to the receiver, to command a spacecraft or to lead the system's owner to erroneous decision. (Citation: MITRE ATT&CK) (Citation: SRC012) (Citation: SRC017)\n\nStandard/references: (Citation: SRC003)","url":"https://spaceshield.esa.int/techniques/T2024","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2024 Transmitted Data Manipulation","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2024","url":"https://spaceshield.esa.int/techniques/T2024"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2026","stixId":"attack-pattern--62e267a5-0f44-4792-a99b-7baa7c4bce54","name":"Temporary loss to telecommand satellite","description":"An attacker can perform actions that temporarily leave the owner without the control on the space resource. During this period the resource can be either under the control of the attacker or not. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC025) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2026","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2026 Temporary loss to telecommand satellite","platforms":["Space-link communication","Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2026","url":"https://spaceshield.esa.int/techniques/T2026"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2026.001","stixId":"attack-pattern--10db2cb8-30e9-4fcb-9e77-b7543121a802","name":"Replace session keys","description":"Adversaries can replace encryption keys used to encrypt TM/TC in order to gain permanent access to other functionalities, or to temporarily interrupt the owner's control. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC025) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2026/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2026.001 Replace session keys","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2026","stixId":"attack-pattern--62e267a5-0f44-4792-a99b-7baa7c4bce54","name":"Temporary loss to telecommand satellite","description":"An attacker can perform actions that temporarily leave the owner without the control on the space resource. During this period the resource can be either under the control of the attacker or not. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC025) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2026"}],"mitigations":[{"id":"SSH.M2002","stixId":"course-of-action--f340a10b-0cc2-4ade-bf9c-5eff01877b3a","name":"Authentication","description":"Authentication permits a secure access to the resource, verifying the actor's identity. It also protects a command or a message from spoofing or modifications. CCSDS SDLS protocol incorporates authentication through MAC. Authentication protects from attacks aiming to access unauthorized resources, to spoof legitimate users, or to manipulate data and communications. (Citation: SRC008) (Citation: SRC017) (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2002"},{"id":"SSH.M2022","stixId":"course-of-action--f7cc4284-b53a-4ed2-a18d-e280f1e4b464","name":"Access control","description":"Access control systems authenticate users and enforce authorization, avoiding that attackers or unauthorized users reach unpermitted services and resources, modify system configurations, and take control of them.\t\nAccess control is needed to identify actors who try to interact with the system, or take place in a network, and it defines if they are authorized or not. \t\nThe installation of backdoors in the system, and the exfiltration of data from it can be prevented or at least made more difficult if an access control is implemented. Furthermore, it can protect from alteration of system settings, disablement of defenses, or from the deletion of logs.\nWithout the access control, the attacker could take control of the asset, abusing the resources, misconfiguring OBCP to hijack or damage it, he can interrupt the provided services or also take possession of the spacecraft, changing the cryptographic keys. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2022"}],"externalReferences":[{"source":"mitre-attack","id":"T2026.001","url":"https://spaceshield.esa.int/techniques/T2026/001"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2027","stixId":"attack-pattern--d51a9bea-62ef-4401-8e6c-7737294aaf76","name":"Permanent loss to telecommand satellite","description":"An attacker can perform actions that permanently leave the owner without the control on the space resource. The resource can be either under the control of the attacker or not, that can act to gain an illegitimate ownership on the resource, or to damage the legitimate owner. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC025) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2027","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2027 Permanent loss to telecommand satellite","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2027","url":"https://spaceshield.esa.int/techniques/T2027"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2027.001","stixId":"attack-pattern--3b933291-20c0-4a0c-8a1c-962f05061804","name":"Replace session and master keys","description":"Adversaries can replace session and master keys in a space resource, to gain permanent access to the resource and permanently prevent the owner access. This attack leads to a definitive loss of the resource. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC025) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2027/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2027.001 Replace session and master keys","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2027","stixId":"attack-pattern--d51a9bea-62ef-4401-8e6c-7737294aaf76","name":"Permanent loss to telecommand satellite","description":"An attacker can perform actions that permanently leave the owner without the control on the space resource. The resource can be either under the control of the attacker or not, that can act to gain an illegitimate ownership on the resource, or to damage the legitimate owner. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC025) (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2027"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2027.001","url":"https://spaceshield.esa.int/techniques/T2027/001"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"SRC025","url":"https://public.ccsds.org/review/CCSDS%20354.0-R-2/354x0r2.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2028 Resource damage","platforms":["Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2077","stixId":"course-of-action--d46bee56-22a4-4ab6-8542-f6e64c7f7616","name":"Supply chain protections","description":"Implement comprehensive security measures to safeguard the supply chain for spacecraft components and software. This includes verifying the integrity and authenticity of parts, conducting regular audits of suppliers, and ensuring secure transportation of critical elements to prevent tampering or compromise.","url":"https://attack.mitre.org/mitigations/M2077"}],"externalReferences":[{"source":"mitre-attack","id":"T2028","url":"https://spaceshield.esa.int/techniques/T2028"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"},{"source":"SRC013","url":"https://doi.org/10.1093/cybsec/tyac008"}]},{"id":"SSH.T2028.004","stixId":"attack-pattern--9c1ae85a-02af-4ead-bc7a-65c3c00d3ba7","name":"Space Debris Impact","description":"A space resource is damaged or destroyed if an impact with space debris happens. Space debris can be produced to harm resources in specific trajectories. (Citation: SRC013) (Citation: SRC017)","url":"https://spaceshield.esa.int/techniques/T2028/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.004 Space Debris Impact","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2028.004","url":"https://spaceshield.esa.int/techniques/T2028/004"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC013","url":"https://doi.org/10.1093/cybsec/tyac008"}]},{"id":"SSH.T2028.005","stixId":"attack-pattern--65317176-7e84-4540-954c-088fad67482e","name":"Physical sabotage","description":"An attacker can physically damage a satellite, with harmful commands or attacking it with another vehicle. Heaters and flow valves of the propulsion subsystem can be moved. Proximity operations with other satellites are possible (kinetic kill vehicles, radiofrequency jammers, lasers, chemical sprayers, high-power microwaves, and robotic mechanisms). Other possible attacks are against critical software subsystems or internal timers. (Citation: SRC016) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.005 Physical sabotage","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[{"id":"SSH.M2021","stixId":"course-of-action--a6067c0c-6f5a-49c6-b5d8-d95487543a26","name":"Physical security","description":"Guards, gates, and other physical security countermeasures, permit to defend facilities from undesirable accesses, sabotages, or damages made on purpose. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2021"}],"externalReferences":[{"source":"mitre-attack","id":"T2028.005","url":"https://spaceshield.esa.int/techniques/T2028/005"}]},{"id":"SSH.T2028.007","stixId":"attack-pattern--9b26d004-2c89-42bf-9665-cf209a58e705","name":"Intentional collision with other satellites","description":"Adversaries can command the satellite to collide other satellites. This results not only in the loss of the resource, but also in a damage of another resource. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2028/007","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.007 Intentional collision with other satellites","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2028.007","url":"https://spaceshield.esa.int/techniques/T2028/007"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2028.009","stixId":"attack-pattern--40f02d93-16a6-4b79-9aa8-71e615b10d8d","name":"Destruction of sensors","description":"An attacker could target and destroy the sensors onboard of a satellite. This may involve damaging optical, infrared, radar, or other sensing equipment critical to the satellite's mission. Destroying sensors can severely impair the satellite’s ability to gather and transmit valuable data, rendering it ineffective or causing mission failure. These sensors are often vital for navigation, Earth observation, and other scientific objectives.","url":"https://attack.mitre.org/techniques/T2028/009","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.009 Destruction of sensors","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2028.009","url":"https://attack.mitre.org/techniques/T2028/009"}]},{"id":"SSH.T2028.010","stixId":"attack-pattern--2536d486-289f-446d-ae56-91b4284420c9","name":"Destruction of receivers","description":"An attacker may attempt to destroy or disable the receivers on a satellite, which are essential for receiving signals from ground stations, other satellites, or mission-specific communications. Destroying or impairing the receivers may render the satellite unable to communicate or receive essential data, leading to a complete loss of functionality. This could involve targeting radio-frequency receivers, optical receivers, or other communication interfaces critical to the satellite’s operation.","url":"https://attack.mitre.org/techniques/T2028/010","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.010 Destruction of receivers","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2028.010","url":"https://attack.mitre.org/techniques/T2028/010"}]},{"id":"SSH.T2028.011","stixId":"attack-pattern--d7ad2736-b1b2-4428-a0a2-09ea02a83a76","name":"Breakdown of counterfeit components","description":"A space resource can be damaged if a specific HW component, built to fail after a specific period, or counterfeit with a low reliability, breaks out. Relevant for ASIC and FPGA. (Citation: SRC017)","url":"https://spaceshield.esa.int/techniques/T2028/011","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.011 Breakdown of counterfeit components","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2028.011","url":"https://spaceshield.esa.int/techniques/T2028/011"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T2028.012","stixId":"attack-pattern--0f39ae17-002c-4ad8-9593-4765da6fe80a","name":"Kinetic attacks","description":"Attackers can use anti-satellite (ASAT) missiles, or other kinetic energy threats, to attack a resource from the ground or from a plane, without the needs of an orbit insertion. Counterspace weapons are characterized by an easily attribution and the generation of space debris. These systems could include payloads such as kinetic kill vehicles, radiofrequency jammers, lasers, chemical sprayers, high-power microwaves, and robotic mechanisms. This last technology is developed to repair satellites or to remove space debris, but its use can be malicious. A nuclear explosion can also be used against all the space segments.","url":"https://spaceshield.esa.int/techniques/T2028/012","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2028.012 Kinetic attacks","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2028","stixId":"attack-pattern--d6953e32-6020-41c5-80e5-54d5e8b4ac31","name":"Resource damage","description":"An attacker can attempt to damage a space resource, to cause a mission loss. (Citation: European Space Agency) (Citation: SRC013) (Citation: SRC016) (Citation: SRC017) (Citation: SRC020)","url":"https://spaceshield.esa.int/techniques/T2028"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2028.012","url":"https://spaceshield.esa.int/techniques/T2028/012"}]},{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2029 In orbit proximity intelligence","platforms":["Space Segment","Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2032","stixId":"course-of-action--170597f4-33a4-4b2c-ba1b-7358d68bdf02","name":"Bulk data link encryption","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2032"},{"id":"SSH.M2003","stixId":"course-of-action--d87c5194-1a09-4d5e-a8f8-5fb53a5e26b9","name":"Encryption of communications","description":"Encryption of communications  hides the message content to unauthorized eavesdropper, ensuring confidentiality. \n\nThe Space Data Link Security Protocol is a standard defined how to apply encryption, authenticated encryption and encryption only (not recommended) for the CCSDS communication at the Data Link Layer.\n\nPayload traffic, if related to network communications, can use specific traffic protocols, e.g., QPEP. Range data shall be also encrypted. (Citation: SRC008) (Citation: SRC017) (Citation: SRC029)","url":"https://spaceshield.esa.int/mitigations/M2003"},{"id":"SSH.M2015","stixId":"course-of-action--d281c8ce-6a5e-4b22-b808-0f714ffcc4c3","name":"Cryptographic DSSS sequence","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof.  If the DSSS sequence is protected by a cryptographic sequence, a cryptographic key is needed to predict the spreading sequence's behavior. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2015"},{"id":"SSH.M2014","stixId":"course-of-action--f8c7ed24-c26c-49c7-a78f-74be6cca3d95","name":"Spread Spectrum","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2014"},{"id":"SSH.M2034","stixId":"course-of-action--c8719f9c-5186-4d4c-9468-3043cdd388a3","name":"Opaque spacecraft design","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2034"},{"id":"SSH.M2016","stixId":"course-of-action--53d273af-6461-4730-a1ff-a754332fa4a0","name":"Frequency Hopping","description":"Frequency Hopping is a system to regularly change the carrier frequency according to a specific pattern. This procedure makes interception more difficult and protects the signal from interference, either deliberated or not.  (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2016"},{"id":"SSH.M2031","stixId":"course-of-action--e51b483e-dc98-434b-9ed6-553468d8b22c","name":"Padding","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2031"},{"id":"SSH.M2030","stixId":"course-of-action--e953c9fb-c9d8-4ec3-9315-b4fd6e3f1db2","name":"Usage of directive transmit antenna","description":"Usage of directive transmit antenna (incl. potentially optical links, antennas with more focused patterns, etc.)","url":"https://spaceshield.esa.int/mitigations/M2030"}],"externalReferences":[{"source":"mitre-attack","id":"T2029","url":"https://attack.mitre.org/techniques/T2029"},{"source":"SRC039","url":"https://public.ccsds.org/Pubs/352x0b2.pdf"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"},{"source":"SRC008","url":"https://public.ccsds.org/Pubs/355x0b2.pdf"},{"source":"SRC038","url":"https://ecss.nl/"},{"source":"European Space Agency","url":"https://www.esa.int"},{"source":"ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz","url":"https://www.itu.int/dms_pubrec/itu-r/rec/s/R-REC-S.1428-1-200102-I!!PDF-E.pdf"}]},{"id":"SSH.T2029.001","stixId":"attack-pattern--668c6bc8-ed0b-4809-99ef-ccbb23065b0d","name":"Optical (visual) reconnaissance","description":"Proximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2029/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2029.001 Optical (visual) reconnaissance","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2029.001","url":"https://spaceshield.esa.int/techniques/T2029/001"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2029.002","stixId":"attack-pattern--bba4d318-6672-4175-9cc6-ffb3153ccc91","name":"Electromagnetic reconnaissance","description":"Proximity intelligence can be electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2029/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2029.002 Electromagnetic reconnaissance","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2029.002","url":"https://spaceshield.esa.int/techniques/T2029/002"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2029.003","stixId":"attack-pattern--9e1fd074-0efe-4bb3-942f-e11fec6ab2a1","name":"Telemetry Protocol Interception","description":"An attacker tries to gain knowledge about the Telemetry implementation, including the authentication and encryption status. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003) (Citation: SRC006) (Citation: SRC010) (Citation: SRC024)","url":"https://spaceshield.esa.int/techniques/T2029/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2029.003 Telemetry Protocol Interception","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2029.003","url":"https://spaceshield.esa.int/techniques/T2029/003"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC010","url":"https://public.ccsds.org/Pubs/132x0b3.pdf"},{"source":"SRC006","url":"https://public.ccsds.org/Pubs/131x0b4.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC024","url":"https://www.wired.com/story/nyansat-open-source-satellite-tracker/"}]},{"id":"SSH.T2029.004","stixId":"attack-pattern--47e6c439-5008-490a-99f1-0c476cb6a091","name":"Telecommand Protocol Interception","description":"An attacker tries to gain knowledge about the Telecommand implementation, including the authentication and encryption status (Citation: SRC017). While the signal is weak, the proximity to the legitimate recipient may render it more suitable in case very narrow beams are used.\n\nStandard/references: (Citation: SRC003) (Citation: SRC005) (Citation: SRC009)","url":"https://spaceshield.esa.int/techniques/T2029/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2029.004 Telecommand Protocol Interception","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2029.004","url":"https://spaceshield.esa.int/techniques/T2029/004"},{"source":"SRC005","url":"https://public.ccsds.org/Pubs/231x0b4e0.pdf"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC009","url":"https://public.ccsds.org/Pubs/232x0b4.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"}]},{"id":"SSH.T2029.005","stixId":"attack-pattern--79fda472-a6db-42ff-8ba2-7f59d9bc8c8e","name":"Mission specific Channel Interception","description":"An attacker tries to gain knowledge about a payload dedicated channel communication, peculiar in a specific mission. The channel can be managed by a different company than the owner of the satellite. Interception includes authentication/encryption schemes and medium access control. (Citation: SRC017)\n\nStandard/references: (Citation: SRC003), (Citation: SRC024)","url":"https://spaceshield.esa.int/techniques/T2029/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2029.005 Mission specific Channel Interception","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2029.005","url":"https://spaceshield.esa.int/techniques/T2029/005"},{"source":"SRC003","url":"https://public.ccsds.org/Pubs/401x0b32.pdf"},{"source":"SRC017","url":"https://public.ccsds.org/Pubs/350x1g3.pdf"},{"source":"SRC024","url":"https://www.wired.com/story/nyansat-open-source-satellite-tracker/"}]},{"id":"SSH.T2029.006","stixId":"attack-pattern--9a729b6c-a8f0-42c3-8fdb-7c87482d6b4a","name":"Traffic Analysis","description":"The attacker intends to determine which entities are communicating with each other without the ability to access the communicated information.\n","url":"https://spaceshield.esa.int/techniques/T2029/006","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2029.006 Traffic Analysis","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0043","name":"Reconnaissance","shortname":"reconnaissance"}],"parentTechniques":[{"id":"SSH.T2029","stixId":"attack-pattern--6c808a79-5bc3-4016-aeb6-6598d37581d4","name":"In orbit proximity intelligence","description":"The attacker, mainly a military organization, can use satellites positioned in proximity to the victim satellite to gather information, visual or radio, on the satellite's capability or on its work. (Citation: European Space Agency)\n\nProximity intelligence can be visual, with cameras or other optical sensors, to gain information about satellite's hardware, or electromagnetic, using antennas to intercept communications or to measure other EM emissions to attempt a side-channel attack.\n\nStandards/references: (Citation: SRC008) (Citation: SRC038) (Citation: SRC039)(Citation: ITU-R S.1428-1, Reference FSS earth-station radiation patterns for use in interference assessment involving non-GSO satellites in frequency bands between 10.7 GHz and 30 GHz)(Citation: SRC014)","url":"https://attack.mitre.org/techniques/T2029"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2029.006","url":"https://spaceshield.esa.int/techniques/T2029/006"}]},{"id":"SSH.T2030","stixId":"attack-pattern--4247afac-ca2e-40b1-ac4f-e9a32d5ba07c","name":"Ground Segment Compromise","description":"Adversaries may compromise Ground Segment using it as a steppingstone to get Initial Access to the Space Segment and the system in general. If an attacker can get access into a Ground Segment that control the targeted spacecraft, then through it he can potentially compromise the spacecraft itself. Ground segment compromise can either by logical, or physical. ","url":"https://spaceshield.esa.int/techniques/T2030","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2030 Ground Segment Compromise","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2042","stixId":"course-of-action--443db6a2-e94f-4b59-9a38-d129269c244c","name":"Secure Design and Implementation of Ground Segment for Space Systems","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2042"},{"id":"SSH.M2017","stixId":"course-of-action--7f7dfa7f-5240-4b57-9ff0-a892779acda5","name":"Monitoring","description":"Monitoring of the system's state to early detect undesirable behaviors or interactions. In case of Denial-of-Service attacks, the Ground Station should be able to notice the status of the receiver. If the receiver is targeted by attacks, the power of the transmitter should be increased, rising the receiver's threshold level, and cutting out the malicious signals.\t\nMonitoring of the radio channel permits the identification of messages sent by unauthorized users towards the spacecraft. Monitoring of the internal system may discover malignant or erroneous operations. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2017"},{"id":"SSH.M2041","stixId":"course-of-action--6acd6f5c-5b82-43ef-bc4c-6258c917da68","name":"Multi-factor authentication","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2041"},{"id":"SSH.M2021","stixId":"course-of-action--a6067c0c-6f5a-49c6-b5d8-d95487543a26","name":"Physical security","description":"Guards, gates, and other physical security countermeasures, permit to defend facilities from undesirable accesses, sabotages, or damages made on purpose. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2021"}],"externalReferences":[{"source":"mitre-attack","id":"T2030","url":"https://spaceshield.esa.int/techniques/T2030"}]},{"id":"SSH.T2030.001","stixId":"attack-pattern--a2a1c6f2-a363-4ec8-b0a0-d6bf91cfbce8","name":"Logical compromise","description":"There can be various ways of Ground Segment compromise, that resemble a lot MITRE ATT&CK® Enterprise methods, which are beyond the scope of this work. (Citation: ASAT Goes Cyber)","url":"https://spaceshield.esa.int/techniques/T2030/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2030.001 Logical compromise","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2030","stixId":"attack-pattern--4247afac-ca2e-40b1-ac4f-e9a32d5ba07c","name":"Ground Segment Compromise","description":"Adversaries may compromise Ground Segment using it as a steppingstone to get Initial Access to the Space Segment and the system in general. If an attacker can get access into a Ground Segment that control the targeted spacecraft, then through it he can potentially compromise the spacecraft itself. Ground segment compromise can either by logical, or physical. ","url":"https://spaceshield.esa.int/techniques/T2030"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2030.001","url":"https://spaceshield.esa.int/techniques/T2030/001"},{"source":"ASAT Goes Cyber","url":"https://www.usni.org/magazines/proceedings/2021/february/asat-goes-cyber"}]},{"id":"SSH.T2030.002","stixId":"attack-pattern--6ae44726-b452-4647-8bc2-991111adaf79","name":"Physical compromise","description":"An attacker can exploit missing physical security ( eg. facilities not protected with physical barriers). ","url":"https://spaceshield.esa.int/techniques/T2030/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2030.002 Physical compromise","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2030","stixId":"attack-pattern--4247afac-ca2e-40b1-ac4f-e9a32d5ba07c","name":"Ground Segment Compromise","description":"Adversaries may compromise Ground Segment using it as a steppingstone to get Initial Access to the Space Segment and the system in general. If an attacker can get access into a Ground Segment that control the targeted spacecraft, then through it he can potentially compromise the spacecraft itself. Ground segment compromise can either by logical, or physical. ","url":"https://spaceshield.esa.int/techniques/T2030"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2030.002","url":"https://spaceshield.esa.int/techniques/T2030/002"}]},{"id":"SSH.T2031","stixId":"attack-pattern--4c638e26-8c83-4642-a8b2-7f3ae670af8f","name":"Become Avionics Bus Master","description":"An attacker can use a compromised device connected to an Avionics Bus to interact with the line and force the election to become the Bus master. This role can be used to disrupt the communication between other nodes. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2031","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2031 Become Avionics Bus Master","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0004","name":"Privilege Escalation","shortname":"privilege-escalation"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2064","stixId":"course-of-action--bb0a83b2-1e13-4f80-8da5-4d75a06faded","name":"Detection techniques of exploitation attempts","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2064"},{"id":"SSH.M2078","stixId":"course-of-action--8808d66a-a723-4923-9576-a04514d08009","name":"Detection of abnormal behaviour at avionics bus / Prevention mechanisms","description":"Intrusion Detection / Prevention Systems for Avionics Bus","url":"https://spaceshield.esa.int/mitigations/M2078"},{"id":"SSH.M2063","stixId":"course-of-action--23966f59-9560-4868-8652-2f397e597e64","name":"Patching to the latest available software version","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2063"}],"externalReferences":[{"source":"mitre-attack","id":"T2031","url":"https://spaceshield.esa.int/techniques/T2031"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2032","stixId":"attack-pattern--8191469a-7aae-4157-b383-ad76933e4de2","name":"Key Management Policy Discovery","description":"Adversaries may try to gather information about Key Management Policy implemented. Security Policies are rules and regulations that describe the operational procedures required for proper key management. This includes the specification of rules for processes such as generation, distribution, and allowed use for cryptographic keys. (Citation: European Space Agency)\n\nStandard/references: (Citation: SRC026)","url":"https://spaceshield.esa.int/techniques/T2032","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2032 Key Management Policy Discovery","platforms":["Ground Segment","Space Segment"],"tactics":[{"id":"SSH.TA0007","name":"Discovery","shortname":"discovery"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2032","url":"https://spaceshield.esa.int/techniques/T2032"},{"source":"SRC026","url":"https://public.ccsds.org/Pubs/350x6g1.pdf"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2033","stixId":"attack-pattern--00fcf4b4-5f4b-41a2-ad96-da4ba03fe257","name":"Trust Relationships Discovery","description":"Adversaries may try to gather information about Trust Relationships with other companies or organizations. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2033","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2033 Trust Relationships Discovery","platforms":["None"],"tactics":[{"id":"SSH.TA0007","name":"Discovery","shortname":"discovery"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2033","url":"https://spaceshield.esa.int/techniques/T2033"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2034","stixId":"attack-pattern--2cc96363-cff3-4062-8eb8-7fb28518142b","name":"Spacecraft's Components Discovery","description":"Adversaries may try to gather information about Components of the Spacecraft, monitoring internal communication, actively communicating with the system, or from internal registries or configurations. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2034","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2034 Spacecraft's Components Discovery","platforms":["None"],"tactics":[{"id":"SSH.TA0007","name":"Discovery","shortname":"discovery"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M1031","stixId":"course-of-action--428eff47-d6ce-4c82-b91b-63d25a294ec9","name":"Network Intrusion Prevention","description":"Use intrusion detection signatures to block traffic at network boundaries. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1031"},{"id":"SSH.M1030","stixId":"course-of-action--c4ac7a18-bbbf-422c-a57e-ed34c531115a","name":"Network Segmentation","description":"Architect sections of the network to isolate critical systems, functions, or resources. Use physical and logical segmentation to prevent access to potentially sensitive systems and information. Use a DMZ to contain any internet-facing services that should not be exposed from the internal network. Configure separate virtual private cloud (VPC) instances to isolate critical cloud systems. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1030"},{"id":"SSH.M2007","stixId":"course-of-action--f24de305-389d-40c0-a78f-77d19f3f5dc6","name":"Partitioning/Separation","description":"Time and Space Partitioning or other satellite hypervisor types should protect systems from mutual interferences, creating security borders between services and preventing unauthorized interactions. (Citation: SRC015)","url":"https://spaceshield.esa.int/mitigations/M2007"}],"externalReferences":[{"source":"mitre-attack","id":"T2034","url":"https://spaceshield.esa.int/techniques/T2034"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2035","stixId":"attack-pattern--2b8e7d03-1ca2-42b3-a942-ba7254c9ef0c","name":"Side-channel exfiltration","description":"An adversarial can exfiltrate data with a side-channel attack. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2035","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2035 Side-channel exfiltration","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0010","name":"Exfiltration","shortname":"exfiltration"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2022","stixId":"course-of-action--f7cc4284-b53a-4ed2-a18d-e280f1e4b464","name":"Access control","description":"Access control systems authenticate users and enforce authorization, avoiding that attackers or unauthorized users reach unpermitted services and resources, modify system configurations, and take control of them.\t\nAccess control is needed to identify actors who try to interact with the system, or take place in a network, and it defines if they are authorized or not. \t\nThe installation of backdoors in the system, and the exfiltration of data from it can be prevented or at least made more difficult if an access control is implemented. Furthermore, it can protect from alteration of system settings, disablement of defenses, or from the deletion of logs.\nWithout the access control, the attacker could take control of the asset, abusing the resources, misconfiguring OBCP to hijack or damage it, he can interrupt the provided services or also take possession of the spacecraft, changing the cryptographic keys. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2022"}],"externalReferences":[{"source":"mitre-attack","id":"T2035","url":"https://spaceshield.esa.int/techniques/T2035"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2036","stixId":"attack-pattern--4d23a950-d04e-4ddd-8440-31843eb9abe0","name":"RF modification","description":"An adversarial can exfiltrate data modifying the RF components to send data with a different timing (and location), or with different frequencies. Antenna array can be used to send data into different beams. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2036","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2036 RF modification","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0010","name":"Exfiltration","shortname":"exfiltration"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2036","url":"https://spaceshield.esa.int/techniques/T2036"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2037","stixId":"attack-pattern--505bf6e6-9ae9-4539-a167-b1715834a7a8","name":"Optical link modification","description":"An adversarial can exfiltrate data modifying the optical communication components to send data with a different timing (and location). (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2037","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2037 Optical link modification","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0010","name":"Exfiltration","shortname":"exfiltration"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2037","url":"https://spaceshield.esa.int/techniques/T2037"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2038","stixId":"attack-pattern--9f261cd4-c5a4-4325-ab42-ffd1c76c138b","name":"Compromise Account","description":"For Space Segment, the accounts are typically the cryptographic keys used to authenticate the execution of telecommands at a spacecraft. \n\nStandards: (Citation: SRC039) (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2038","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2038 Compromise Account","platforms":["Ground Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2037","stixId":"course-of-action--4b8391e3-debe-4784-a90e-1d36dbdbecea","name":"Digital certificates","description":"CCSDS 357.0-B-1","url":"https://spaceshield.esa.int/mitigations/M2037"},{"id":"SSH.M2060","stixId":"course-of-action--dbc85852-b7bf-43e7-94ee-9fb6d459164b","name":"Establish processes, procedures, and security measures to protect cryptographic keys / key management","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2060"}],"externalReferences":[{"source":"mitre-attack","id":"T2038","url":"https://spaceshield.esa.int/techniques/T2038"},{"source":"SRC039","url":"https://public.ccsds.org/Pubs/352x0b2.pdf"},{"source":"SRC014","url":"https://public.ccsds.org/Pubs/357x0b1.pdf"}]},{"id":"SSH.T2038.001","stixId":"attack-pattern--cb1992be-4de5-44e7-ba54-47e1dfa3a2d0","name":"Brute forcing","description":"Brute force telecommand access to satellite by trying different keys","url":"https://spaceshield.esa.int/techniques/T2038/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2038.001 Brute forcing","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0042","name":"Resource Development","shortname":"resource-development"}],"parentTechniques":[{"id":"SSH.T2038","stixId":"attack-pattern--9f261cd4-c5a4-4325-ab42-ffd1c76c138b","name":"Compromise Account","description":"For Space Segment, the accounts are typically the cryptographic keys used to authenticate the execution of telecommands at a spacecraft. \n\nStandards: (Citation: SRC039) (Citation: SRC014)","url":"https://spaceshield.esa.int/techniques/T2038"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2038.001","url":"https://spaceshield.esa.int/techniques/T2038/001"}]},{"id":"SSH.T2039","stixId":"attack-pattern--fe19b8b8-b187-46e1-bc0c-52ddd861c007","name":"Trusted Relationship","description":"An attacker can compromise another system which can be used to get access to an interconnected one by exploiting a trusted relationship between the two. In space missions context this can be e.g. in case of Federated missions.   ","url":"https://spaceshield.esa.int/techniques/T2039","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2039 Trusted Relationship","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2041","stixId":"course-of-action--6acd6f5c-5b82-43ef-bc4c-6258c917da68","name":"Multi-factor authentication","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2041"},{"id":"SSH.M2043","stixId":"course-of-action--7d79fc3e-800a-456a-a1b1-188639eb1ea3","name":"Zero Trust Architecture","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2043"},{"id":"SSH.M2044","stixId":"course-of-action--a0ef4fa1-78f3-43ef-a7a8-fa4dee689558","name":"Application of Least Privilege principle","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2044"}],"externalReferences":[{"source":"mitre-attack","id":"T2039","url":"https://spaceshield.esa.int/techniques/T2039"}]},{"id":"SSH.T2039.001","stixId":"attack-pattern--ac9f74ec-f237-476a-998a-f844585ec6c7","name":"External Entities interconnected to main mission","description":"An attacker can compromise the system of a contractor company, to steal, modify or damage resources. A scientific or another connected company/research institution can be compromised for the same objective. Connected networks or data exchanges can be leveraged to propagate the attack.","url":"https://spaceshield.esa.int/techniques/T2039/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2039.001 External Entities interconnected to main mission","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2039","stixId":"attack-pattern--fe19b8b8-b187-46e1-bc0c-52ddd861c007","name":"Trusted Relationship","description":"An attacker can compromise another system which can be used to get access to an interconnected one by exploiting a trusted relationship between the two. In space missions context this can be e.g. in case of Federated missions.   ","url":"https://spaceshield.esa.int/techniques/T2039"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2039.001","url":"https://spaceshield.esa.int/techniques/T2039/001"}]},{"id":"SSH.T2039.002","stixId":"attack-pattern--16f81494-2a64-447a-9c78-0170d9234ac7","name":"Federated missions","description":"In federated missions, where multiple organizations collaborate, an attacker can exploit the trust relationships between them. By compromising one component of the federation, the attacker can gain access to other interconnected assets within the mission, potentially leading to the compromise of critical mission functions.","url":"https://attack.mitre.org/techniques/T2039/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2039.002 Federated missions","platforms":["None"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2039","stixId":"attack-pattern--fe19b8b8-b187-46e1-bc0c-52ddd861c007","name":"Trusted Relationship","description":"An attacker can compromise another system which can be used to get access to an interconnected one by exploiting a trusted relationship between the two. In space missions context this can be e.g. in case of Federated missions.   ","url":"https://spaceshield.esa.int/techniques/T2039"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2039.002","url":"https://attack.mitre.org/techniques/T2039/002"}]},{"id":"SSH.T2039.003","stixId":"attack-pattern--fcc6062e-947b-421f-aa26-7a55b6c0d963","name":"Interconnected spacecrafts","description":"An attacker cam leverage the interconnection to another spacecraft to compromise it in to order to, in the end, compromise the target","url":"https://spaceshield.esa.int/techniques/T2039/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2039.003 Interconnected spacecrafts","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0001","name":"Initial Access","shortname":"initial-access"}],"parentTechniques":[{"id":"SSH.T2039","stixId":"attack-pattern--fe19b8b8-b187-46e1-bc0c-52ddd861c007","name":"Trusted Relationship","description":"An attacker can compromise another system which can be used to get access to an interconnected one by exploiting a trusted relationship between the two. In space missions context this can be e.g. in case of Federated missions.   ","url":"https://spaceshield.esa.int/techniques/T2039"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2039.003","url":"https://spaceshield.esa.int/techniques/T2039/003"}]},{"id":"SSH.T2040","stixId":"attack-pattern--ae67cbbd-7325-452d-99b9-1166188a356f","name":"Masquerading","description":"Adversaries may attempt to manipulate features of their artifacts to make them appear legitimate or benign to users and/or security tools  (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2040","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2040 Masquerading","platforms":["None"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2072","stixId":"course-of-action--5d37f516-ce33-43b8-bd8a-51c8bfb4617a","name":"Authentication mechanisms using approved cryptographic means","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2072"}],"externalReferences":[{"source":"mitre-attack","id":"T2040","url":"https://spaceshield.esa.int/techniques/T2040"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2041","stixId":"attack-pattern--de674bfd-5a0e-497c-b781-0edd80580622","name":"Pre-Os Boot","description":"Pre-OS Boot can also be abused to evade defensive mechanisms that are potentially in place at higher level, i.e. at application layer.","url":"https://spaceshield.esa.int/techniques/T2041","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2041 Pre-Os Boot","platforms":["Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M1046","stixId":"course-of-action--40f3b623-2abd-4311-a016-8b1a2aff979d","name":"Boot Integrity","description":"Use secure methods to boot a system and verify the integrity of the operating system and loading mechanisms. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/mitigations/M1046"}],"externalReferences":[{"source":"mitre-attack","id":"T2041","url":"https://spaceshield.esa.int/techniques/T2041"}]},{"id":"SSH.T2041.001","stixId":"attack-pattern--98b31f43-f6a2-45f0-a33a-da72f0150a7d","name":"System Firmware Exploitation","description":"Persistence at a pre-OS level can be gained modifying the firmware in a resource.\nSystem firmware is quite static, and it doesn't usually provide detections capabilities. A firmware level manipulation can remain unnoticed until next phases of the attack. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2041/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2041.001 System Firmware Exploitation","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0005","name":"Defense Evasion","shortname":"defense-evasion"}],"parentTechniques":[{"id":"SSH.T2041","stixId":"attack-pattern--de674bfd-5a0e-497c-b781-0edd80580622","name":"Pre-Os Boot","description":"Pre-OS Boot can also be abused to evade defensive mechanisms that are potentially in place at higher level, i.e. at application layer.","url":"https://spaceshield.esa.int/techniques/T2041"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2041.001","url":"https://spaceshield.esa.int/techniques/T2041/001"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2042","stixId":"attack-pattern--af91d269-17cc-4d70-ba9a-057a028c444c","name":"Adversary in the Middle","description":"Adversaries may attempt to position themselves between two or more networked devices using an adversary-in-the-middle (AiTM) technique.","url":"https://spaceshield.esa.int/techniques/T2042","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2042 Adversary in the Middle","platforms":["Space-link communication","Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2067","stixId":"course-of-action--fac12398-47a2-4829-afa7-3d1f22a531bf","name":"Authentication combined with means to ensure the identity of the other party using certificates or pre-shared keys","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2067"}],"externalReferences":[{"source":"mitre-attack","id":"T2042","url":"https://spaceshield.esa.int/techniques/T2042"}]},{"id":"SSH.T2042.001","stixId":"attack-pattern--79181d2c-3a91-4927-b639-69d227a38071","name":"Lower Orbit Satellites, or Drones","description":"An attacker can take advantage of a drone or any satellite located between the target and the ground station to sniff the communication link.","url":"https://spaceshield.esa.int/techniques/T2042/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2042.001 Lower Orbit Satellites, or Drones","platforms":["Space Segment","Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[{"id":"SSH.T2042","stixId":"attack-pattern--af91d269-17cc-4d70-ba9a-057a028c444c","name":"Adversary in the Middle","description":"Adversaries may attempt to position themselves between two or more networked devices using an adversary-in-the-middle (AiTM) technique.","url":"https://spaceshield.esa.int/techniques/T2042"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2042.001","url":"https://spaceshield.esa.int/techniques/T2042/001"}]},{"id":"SSH.T2043","stixId":"attack-pattern--e5218f36-de44-402b-a08a-0a8422119a2a","name":"Brute Force","description":"Adversaries may use brute force techniques to issue Telecommands and identify the used key(s).","url":"https://spaceshield.esa.int/techniques/T2043","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2043 Brute Force","platforms":["None"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2075","stixId":"course-of-action--25926460-2ad8-4da2-b0c2-480a0cec633e","name":"Use keys of sufficient length","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2075"}],"externalReferences":[{"source":"mitre-attack","id":"T2043","url":"https://spaceshield.esa.int/techniques/T2043"}]},{"id":"SSH.T2043.001","stixId":"attack-pattern--68e3592a-4b3c-4e42-be9e-d948e8cb8f10","name":"TC Brute Forcing","description":"An attacker can use brute force to gain access to a TC channel, to force encryption or to guess the valid commands.","url":"https://spaceshield.esa.int/techniques/T2043/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2043.001 TC Brute Forcing","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[{"id":"SSH.T2043","stixId":"attack-pattern--e5218f36-de44-402b-a08a-0a8422119a2a","name":"Brute Force","description":"Adversaries may use brute force techniques to issue Telecommands and identify the used key(s).","url":"https://spaceshield.esa.int/techniques/T2043"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2043.001","url":"https://spaceshield.esa.int/techniques/T2043/001"}]},{"id":"SSH.T2044","stixId":"attack-pattern--c0acc9a0-904e-4445-96f9-9718048059c2","name":"Communication Link Sniffing","description":"Adversaries may sniff the communication link to attempt to capture information about an environment, including authentication material passed over the network. ","url":"https://spaceshield.esa.int/techniques/T2044","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2044 Communication Link Sniffing","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2068","stixId":"course-of-action--b2a3c805-447c-40d3-b0dc-59d2250c7458","name":"Authenticated encryption","description":"Authenticated encryption is a cryptographic technique that ensures both the confidentiality and authenticity of data. Authenticated encryption is crucial in preventing adversaries from intercepting and manipulating data, as it secures communication against both unauthorized access and tampering.\n\nThis method ensures that even if an adversary intercepts the data, they cannot decrypt it or alter its integrity without detection.\n\nImplementing protocols such as the CCSDS SDLS, which incorporates encryption, authentication, and authenticated encryption is essential for protecting space-link communications.","url":"https://attack.mitre.org/mitigations/M2068"}],"externalReferences":[{"source":"mitre-attack","id":"T2044","url":"https://spaceshield.esa.int/techniques/T2044"}]},{"id":"SSH.T2044.001","stixId":"attack-pattern--5569371a-6479-4cd9-8df8-1d8cbc5668e4","name":"RF sniffing","description":"An attacker can sniff the radio frequency channels to capture potential authentication material.","url":"https://spaceshield.esa.int/techniques/T2044/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2044.001 RF sniffing","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0006","name":"Credential Access","shortname":"credential-access"}],"parentTechniques":[{"id":"SSH.T2044","stixId":"attack-pattern--c0acc9a0-904e-4445-96f9-9718048059c2","name":"Communication Link Sniffing","description":"Adversaries may sniff the communication link to attempt to capture information about an environment, including authentication material passed over the network. ","url":"https://spaceshield.esa.int/techniques/T2044"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2044.001","url":"https://spaceshield.esa.int/techniques/T2044/001"}]},{"id":"SSH.T2045","stixId":"attack-pattern--055e1217-03cd-475e-ad44-5bf564623b54","name":"Compromise a Payload after compromising the main satellite platform","description":"An attacker can exploit vulnerabilities in the main satellite platform to gain access to its payload. This could involve modifying or taking control of the payload's hardware or software, either to disable it, manipulate its data, or use it for further exploitation. This compromise can happen if the main satellite's integrity is compromised and the attacker uses that foothold to access and manipulate payload operations or functionality.","url":"https://attack.mitre.org/techniques/T2045","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2045 Compromise a Payload after compromising the main satellite platform","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0008","name":"Lateral Movement","shortname":"lateral-movement"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2045","url":"https://attack.mitre.org/techniques/T2045"}]},{"id":"SSH.T2046","stixId":"attack-pattern--c7c1247e-cab7-4322-a717-5ee934514195","name":"Compromise the satellite platform starting from a compromised payload","description":"An attacker can begin by compromising the payload of a satellite, exploiting vulnerabilities in its software or hardware. From there, the attacker can escalate their access to the satellite's main platform, potentially gaining control over critical systems, communications, and payload operations.","url":"https://attack.mitre.org/techniques/T2046","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2046 Compromise the satellite platform starting from a compromised payload","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0008","name":"Lateral Movement","shortname":"lateral-movement"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2046","url":"https://attack.mitre.org/techniques/T2046"}]},{"id":"SSH.T2046.001","stixId":"attack-pattern--c794809c-ff75-49a5-9e39-64b8a60c7740","name":"Inter-Task Compromise","description":"A compromised task is able to exploit inadequate memory isolation policies and compromise the Confidentiality, Integrity and/or Availability of another task's assets. The two tasks are running in the same execution environment. (Citation: MORA: Hunting Space Bugs in your Sleep)","url":"https://spaceshield.esa.int/techniques/T2046/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2046.001 Inter-Task Compromise","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0008","name":"Lateral Movement","shortname":"lateral-movement"}],"parentTechniques":[{"id":"SSH.T2046","stixId":"attack-pattern--c7c1247e-cab7-4322-a717-5ee934514195","name":"Compromise the satellite platform starting from a compromised payload","description":"An attacker can begin by compromising the payload of a satellite, exploiting vulnerabilities in its software or hardware. From there, the attacker can escalate their access to the satellite's main platform, potentially gaining control over critical systems, communications, and payload operations.","url":"https://attack.mitre.org/techniques/T2046"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2046.001","url":"https://spaceshield.esa.int/techniques/T2046/001"},{"source":"MORA: Hunting Space Bugs in your Sleep","url":"https://resolver.tudelft.nl/uuid:0a8ebae7-d6c0-4c19-acb1-22937316b033"}]},{"id":"SSH.T2046.002","stixId":"attack-pattern--ec754c37-b185-4de8-b338-9e86dc91b321","name":"Inter-Application Compromise","description":"In hypervisor environments, a compromised guest application can abuse design or implementation issues to interact with another application. The results of this actions is unintended behavior of the system that could possibly corrupt the systems nominal execution and break the spatial isolation promise of the hypervisor. (Citation: MORA: Hunting Space Bugs in your Sleep)","url":"https://spaceshield.esa.int/techniques/T2046/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2046.002 Inter-Application Compromise","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0008","name":"Lateral Movement","shortname":"lateral-movement"}],"parentTechniques":[{"id":"SSH.T2046","stixId":"attack-pattern--c7c1247e-cab7-4322-a717-5ee934514195","name":"Compromise the satellite platform starting from a compromised payload","description":"An attacker can begin by compromising the payload of a satellite, exploiting vulnerabilities in its software or hardware. From there, the attacker can escalate their access to the satellite's main platform, potentially gaining control over critical systems, communications, and payload operations.","url":"https://attack.mitre.org/techniques/T2046"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2046.002","url":"https://spaceshield.esa.int/techniques/T2046/002"},{"source":"MORA: Hunting Space Bugs in your Sleep","url":"https://resolver.tudelft.nl/uuid:0a8ebae7-d6c0-4c19-acb1-22937316b033"}]},{"id":"SSH.T2047","stixId":"attack-pattern--d9635910-2aa8-4a20-848f-4d8f9c344005","name":"Protocol Tunnelling","description":"Adversaries may tunnel network communications to and from a victim system within a separate protocol to avoid detection/network filtering and/or enable access to otherwise unreachable systems. Tunneling involves explicitly encapsulating a protocol within another.\nThis behavior may conceal malicious traffic by blending in with existing traffic and/or provide an outer layer of encryption  (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2047","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2047 Protocol Tunnelling","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0011","name":"Command and Control","shortname":"command-and-control"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2047","url":"https://spaceshield.esa.int/techniques/T2047"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2048","stixId":"attack-pattern--70fa88ad-1961-4cfc-9321-41e3dec5f464","name":"TT&C over ISL","description":"If the attacker has already managed to issue Telcommands to a spacecraft, then, if Inter Satellite Links (ISL) are used, he can attempt to issue Telecommands to other spacecrafts over the ISLs. ","url":"https://spaceshield.esa.int/techniques/T2048","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2048 TT&C over ISL","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0011","name":"Command and Control","shortname":"command-and-control"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2048","url":"https://spaceshield.esa.int/techniques/T2048"}]},{"id":"SSH.T2049","stixId":"attack-pattern--2d94452e-b662-4177-84cf-a3af1dfbfb31","name":"Spacecraft Jamming","description":"If the victim uses a free space (over the air) communication, it can be threatened by jamming attacks. An attacker can perform a Denial of Service (DoS) attack to limit or block the service availability through RF jamming.\tFor Proximity-1 jamming becomes difficult, because of high distance from Earth (upload) and the use of commercial frequencies (download jamming would affect a lot of other terrestrial links). Jamming of the ranging signal could lead to the total loss of ranging data, and potential navigation errors. ","url":"https://spaceshield.esa.int/techniques/T2049","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2049 Spacecraft Jamming","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2016","stixId":"course-of-action--53d273af-6461-4730-a1ff-a754332fa4a0","name":"Frequency Hopping","description":"Frequency Hopping is a system to regularly change the carrier frequency according to a specific pattern. This procedure makes interception more difficult and protects the signal from interference, either deliberated or not.  (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2016"},{"id":"SSH.M2014","stixId":"course-of-action--f8c7ed24-c26c-49c7-a78f-74be6cca3d95","name":"Spread Spectrum","description":"Spread Spectrum is a system to spread the signal power over a large frequency band, hiding the signal itself and protecting it. Reconstructing the original signal needs the knowledge of the spreading sequence. The resulting signal is more difficult to find and intercept, to jam or to spoof. (Citation: SRC017)","url":"https://spaceshield.esa.int/mitigations/M2014"}],"externalReferences":[{"source":"mitre-attack","id":"T2049","url":"https://spaceshield.esa.int/techniques/T2049"}]},{"id":"SSH.T2049.001","stixId":"attack-pattern--d0f04440-0a1d-49b8-b563-ca126d33b498","name":"Receiver lock on a spurious carrier","description":"The lock of the spacecraft receiver or of the ground station with a continuous wave or with the obtained DSSS sequence can be a threat. Increasing the power is the only way to unlock the receiver, or it unlocks when the spacecraft moves out of LOS with the attacker GS. The attack depends on the receiver and on the system dynamic, that causes the doppler effect and requires a major bandwidth. A possible mitigation is the cryptographic DSSS sequence.(Citation: European Space Agency)\n","url":"https://spaceshield.esa.int/techniques/T2049/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2049.001 Receiver lock on a spurious carrier","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2049","stixId":"attack-pattern--2d94452e-b662-4177-84cf-a3af1dfbfb31","name":"Spacecraft Jamming","description":"If the victim uses a free space (over the air) communication, it can be threatened by jamming attacks. An attacker can perform a Denial of Service (DoS) attack to limit or block the service availability through RF jamming.\tFor Proximity-1 jamming becomes difficult, because of high distance from Earth (upload) and the use of commercial frequencies (download jamming would affect a lot of other terrestrial links). Jamming of the ranging signal could lead to the total loss of ranging data, and potential navigation errors. ","url":"https://spaceshield.esa.int/techniques/T2049"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2049.001","url":"https://spaceshield.esa.int/techniques/T2049/001"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2049.002","stixId":"attack-pattern--c81b55a3-8776-4c95-940f-88dcf7712661","name":"Optical Jamming (Links/Sensor Blinding)","description":"An attacker can conduct optical attacks with high power laser beams to target optical sensors or optical links. If the payload uses cameras or other optical sensors to take pictures or measurements, they can be blinded or damaged.\n (Citation: European Space Agency) (Citation: SRC030) (Citation: SRC031) (Citation: soviet lasers)","url":"https://spaceshield.esa.int/techniques/T2049/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2049.002 Optical Jamming (Links/Sensor Blinding)","platforms":["Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2049","stixId":"attack-pattern--2d94452e-b662-4177-84cf-a3af1dfbfb31","name":"Spacecraft Jamming","description":"If the victim uses a free space (over the air) communication, it can be threatened by jamming attacks. An attacker can perform a Denial of Service (DoS) attack to limit or block the service availability through RF jamming.\tFor Proximity-1 jamming becomes difficult, because of high distance from Earth (upload) and the use of commercial frequencies (download jamming would affect a lot of other terrestrial links). Jamming of the ranging signal could lead to the total loss of ranging data, and potential navigation errors. ","url":"https://spaceshield.esa.int/techniques/T2049"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2049.002","url":"https://spaceshield.esa.int/techniques/T2049/002"},{"source":"SRC030","url":"https://thespacereview.com/article/4416/1"},{"source":"European Space Agency","url":"https://www.esa.int"},{"source":"SRC031","url":"https://ieeexplore.ieee.org/document/8922767"},{"source":"soviet lasers","url":"https://www.upi.com/Archives/1988/01/23/Exclusive-Graphic-Soviet-lasers-said-to-zap-US-spy-satellites/8407569912400/"}]},{"id":"SSH.T2049.003","stixId":"attack-pattern--2caa7369-c9ef-4804-9326-20dae891e594","name":"SDR buffer overflow","description":"If SDRs or digital signal processing software are used to provide radio functionality, insufficient checks in radio frame processing, coupled with malformed data packets, could lead to buffer overflows, and create denial-of-service conditions. This type of jamming is significantly stealthier as it is triggered by sending a small number of packets and doesn't require a continuous RF jamming signal.","url":"https://spaceshield.esa.int/techniques/T2049/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2049.003 SDR buffer overflow","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2049","stixId":"attack-pattern--2d94452e-b662-4177-84cf-a3af1dfbfb31","name":"Spacecraft Jamming","description":"If the victim uses a free space (over the air) communication, it can be threatened by jamming attacks. An attacker can perform a Denial of Service (DoS) attack to limit or block the service availability through RF jamming.\tFor Proximity-1 jamming becomes difficult, because of high distance from Earth (upload) and the use of commercial frequencies (download jamming would affect a lot of other terrestrial links). Jamming of the ranging signal could lead to the total loss of ranging data, and potential navigation errors. ","url":"https://spaceshield.esa.int/techniques/T2049"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2049.003","url":"https://spaceshield.esa.int/techniques/T2049/003"}]},{"id":"SSH.T2050","stixId":"attack-pattern--daaef56a-f677-4aaf-b397-693f0cf496af","name":"Ground Segment Jamming","description":"An attacker can jam the communication to prevent data being delivered. TT&C: Usually is possible to wait and communicate later without noticeable problems. Proximity-1: jamming is difficult, because of high distance from Earth (upload) or the use of commercial frequencies (download jamming would affect lot of other terrestrial links). Jamming of the ranging signal could lead to the total loss of ranging data, and potential navigation errors. C&S Sublayer provides methods for frame re-synchronization.","url":"https://spaceshield.esa.int/techniques/T2050","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2050 Ground Segment Jamming","platforms":["Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2050","url":"https://spaceshield.esa.int/techniques/T2050"}]},{"id":"SSH.T2050.001","stixId":"attack-pattern--2edc0a5b-1e20-4af0-acbb-28974cb9a3a3","name":"Jamming from the ground","description":"TBD","url":"https://spaceshield.esa.int/techniques/T2050/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2050.001 Jamming from the ground","platforms":["Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2050","stixId":"attack-pattern--daaef56a-f677-4aaf-b397-693f0cf496af","name":"Ground Segment Jamming","description":"An attacker can jam the communication to prevent data being delivered. TT&C: Usually is possible to wait and communicate later without noticeable problems. Proximity-1: jamming is difficult, because of high distance from Earth (upload) or the use of commercial frequencies (download jamming would affect lot of other terrestrial links). Jamming of the ranging signal could lead to the total loss of ranging data, and potential navigation errors. C&S Sublayer provides methods for frame re-synchronization.","url":"https://spaceshield.esa.int/techniques/T2050"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2050.001","url":"https://spaceshield.esa.int/techniques/T2050/001"}]},{"id":"SSH.T2050.002","stixId":"attack-pattern--072c8ced-a1c2-4ae4-a5a6-311518a46005","name":"Jamming from a large (LEO) constellation from space","description":"missing","url":"https://spaceshield.esa.int/techniques/T2050/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2050.002 Jamming from a large (LEO) constellation from space","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2050.002","url":"https://spaceshield.esa.int/techniques/T2050/002"}]},{"id":"SSH.T2052","stixId":"attack-pattern--2ef497f5-52c3-47a0-a02b-7eae3a52a08f","name":"Saturation of Inter Satellite Links","description":"In a network constellation without an efficient routing protocol, a network attack aiming to flood the network is possible, causing a saturation of an intersatellite link. This kind of attack can be executed by authorized users, intentionally or not (botnet malware on user devices).","url":"https://spaceshield.esa.int/techniques/T2052","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2052 Saturation of Inter Satellite Links","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2071","stixId":"course-of-action--54b50705-4925-44a9-935b-f0640321f72a","name":"Dynamic Routing","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2071"}],"externalReferences":[{"source":"mitre-attack","id":"T2052","url":"https://spaceshield.esa.int/techniques/T2052"}]},{"id":"SSH.T2052.001","stixId":"attack-pattern--6d11e044-fc56-4b04-b561-c9d16dc029fa","name":"Coremelt attacks","description":"TBD","url":"https://spaceshield.esa.int/techniques/T2052/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2052.001 Coremelt attacks","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2052","stixId":"attack-pattern--2ef497f5-52c3-47a0-a02b-7eae3a52a08f","name":"Saturation of Inter Satellite Links","description":"In a network constellation without an efficient routing protocol, a network attack aiming to flood the network is possible, causing a saturation of an intersatellite link. This kind of attack can be executed by authorized users, intentionally or not (botnet malware on user devices).","url":"https://spaceshield.esa.int/techniques/T2052"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2052.001","url":"https://spaceshield.esa.int/techniques/T2052/001"}]},{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2053 Saturation/Exhaustion of Spacecraft Resources","platforms":["Space-link communication","Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2002","stixId":"course-of-action--f340a10b-0cc2-4ade-bf9c-5eff01877b3a","name":"Authentication","description":"Authentication permits a secure access to the resource, verifying the actor's identity. It also protects a command or a message from spoofing or modifications. CCSDS SDLS protocol incorporates authentication through MAC. Authentication protects from attacks aiming to access unauthorized resources, to spoof legitimate users, or to manipulate data and communications. (Citation: SRC008) (Citation: SRC017) (Citation: European Space Agency)","url":"https://spaceshield.esa.int/mitigations/M2002"},{"id":"SSH.M2076","stixId":"course-of-action--9df9c5df-d1a7-4b29-a25f-4fb47d05678d","name":"Overloading / flooding detection mechanisms","description":"TBD","url":"https://spaceshield.esa.int/mitigations/M2076"}],"externalReferences":[{"source":"mitre-attack","id":"T2053","url":"https://spaceshield.esa.int/techniques/T2053"}]},{"id":"SSH.T2053.001","stixId":"attack-pattern--ec18fd49-e567-4558-a68f-67a13a185c9e","name":"Receiver flooding","description":"An attacker can try to flood the spacecraft receiver sending great amount of data, valid or not. Since the Ground Station notices the status of the receiver, the power of the transmitter should increase to unlock the receiver from the messages flood, rising the receiver's threshold and cutting out the malicious signal. (Citation: European Space Agency)","url":"https://spaceshield.esa.int/techniques/T2053/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.001 Receiver flooding","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.001","url":"https://spaceshield.esa.int/techniques/T2053/001"},{"source":"European Space Agency","url":"https://www.esa.int"}]},{"id":"SSH.T2053.002","stixId":"attack-pattern--7306e9b7-ad8b-4a6e-966f-9711048da0e2","name":"Avionics Bus Flooding","description":"This technique involves overwhelming the avionics bus by injecting an excessive volume of messages, leading to the saturation or exhaustion of communication resources. An attacker can achieve this by gaining control over an ECU (Electronic Control Unit) or microcontroller with access to the bus (e.g., on the CAN bus). This access may be obtained through exploitation of system vulnerabilities or by physically connecting a compromised device to the bus. By flooding the bus with high-priority messages, the attacker can suppress lower-priority communications, causing delays, denial of service, or complete failure of mission-critical operations. ","url":"https://attack.mitre.org/techniques/T2053/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.002 Avionics Bus Flooding","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.002","url":"https://attack.mitre.org/techniques/T2053/002"}]},{"id":"SSH.T2053.003","stixId":"attack-pattern--91961cd6-2ce6-425a-889c-c93e6a03a60d","name":"OBC overloading","description":"TBD","url":"https://spaceshield.esa.int/techniques/T2053/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.003 OBC overloading","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.003","url":"https://spaceshield.esa.int/techniques/T2053/003"}]},{"id":"SSH.T2053.004","stixId":"attack-pattern--f3b21f95-b385-491a-9aa1-b7ad69ec4de3","name":"Drain satellite's power","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping on cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result.(Citation: SRC012)","url":"https://spaceshield.esa.int/techniques/T2053/004","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.004 Drain satellite's power","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.004","url":"https://spaceshield.esa.int/techniques/T2053/004"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T2053.005","stixId":"attack-pattern--f7f7e5ef-5881-4ef3-98d5-3aaf5afbd559","name":"Waste of propellant","description":"An attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life. (Citation: SRC012)","url":"https://spaceshield.esa.int/techniques/T2053/005","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.005 Waste of propellant","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.005","url":"https://spaceshield.esa.int/techniques/T2053/005"},{"source":"SRC012","url":"https://link.springer.com/article/10.1007/s10207-020-00503-w"}]},{"id":"SSH.T2053.006","stixId":"attack-pattern--84bcebee-62bf-43fa-ae9d-435be04c56de","name":"RTOS Scheduler Compromise","description":"This involves manipulating the RTOS scheduler to delay or deny the execution of critical tasks, potentially impacting satellite operations like Attitude Determination and Control System (ADCS) or Electrical Power System (EPS) management. (Citation: MORA: Hunting Space Bugs in your Sleep)","url":"https://spaceshield.esa.int/techniques/T2053/006","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.006 RTOS Scheduler Compromise","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.006","url":"https://spaceshield.esa.int/techniques/T2053/006"},{"source":"MORA: Hunting Space Bugs in your Sleep","url":"https://resolver.tudelft.nl/uuid:0a8ebae7-d6c0-4c19-acb1-22937316b033"}]},{"id":"SSH.T2053.007","stixId":"attack-pattern--c1d37c64-007e-4439-b129-c9f74fca9a7d","name":"Hypervisor Scheduling Compromise","description":"A malicious applications compromises the underlying hypervisor's scheduler by delaying or forcing changes in the scheduling. This behavior impacts the behavior of the other applications running in the same context and potentially leads the system to misbehave and break the spatial isolation promise. (Citation: MORA: Hunting Space Bugs in your Sleep)","url":"https://spaceshield.esa.int/techniques/T2053/007","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2053.007 Hypervisor Scheduling Compromise","platforms":["Space Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2053","stixId":"attack-pattern--51d8cf33-70bf-4a3e-b4b5-9878585799a1","name":"Saturation/Exhaustion of Spacecraft Resources","description":"The attacker can target satellites with energy or resource constraints to lead them prioritizing power saving efforts and disabling security controls. The satellite becomes then more vulnerable to other attacks such as gaining unauthorized access or eavesdropping cleartext communications. This goal can be reached with a regenerative payload \"flooding\", sending to the satellite more packets than expected to rapidly consume its energy. The exploitation of a payload application can achieve a similar result. The attacker can abuse the satellite bandwidth for the retransmission of own content.\n\nThe attacker can maliciously consume satellite propellant resources to achieve the goal of reducing satellite life.\t\n\nThe trajectory of a Space Resource can be changed to waste its resources, to prevent the Resource from doing its purpose, to create an irrecoverable damage or to use the resource for malicious actions.\n","url":"https://spaceshield.esa.int/techniques/T2053"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2053.007","url":"https://spaceshield.esa.int/techniques/T2053/007"},{"source":"MORA: Hunting Space Bugs in your Sleep","url":"https://resolver.tudelft.nl/uuid:0a8ebae7-d6c0-4c19-acb1-22937316b033"}]},{"id":"SSH.T2054","stixId":"attack-pattern--b4a1b631-468e-4076-ad98-54cca318b610","name":"Data Manipulation","description":"Adversaries may insert, delete, or manipulate data in order to influence external outcomes or hide activity, thus threatening the integrity of the data. By manipulating data, adversaries may attempt to affect a business process, organizational understanding, or decision making. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2054","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2054 Data Manipulation","platforms":["Space Segment","Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[{"id":"SSH.M2008","stixId":"course-of-action--feb1223f-a844-4cc8-84ed-2442a2d09f0f","name":"MMU and MPU","description":"For secure spacecraft avionics, protection against read/write and execution access is necessary. The MMU or a MPU provide it, extremely important if the payload is not trusted. (Citation: SRC015)","url":"https://spaceshield.esa.int/mitigations/M2008"}],"externalReferences":[{"source":"mitre-attack","id":"T2054","url":"https://spaceshield.esa.int/techniques/T2054"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2054.001","stixId":"attack-pattern--507793f1-4b7d-440c-b2eb-f950db705825","name":"Stored Data Manipulation","description":"An attacker can alter or corrupt stored data within a system, such as mission control databases, payload data storage, or onboard systems. Manipulating stored data can lead to incorrect decision-making, confusion, or operational errors, especially if the data is used for mission-critical analysis or operations. Preventive measures include employing encryption, access control, and integrity-checking mechanisms to ensure the authenticity and reliability of the stored data.","url":"https://attack.mitre.org/techniques/T2054/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2054.001 Stored Data Manipulation","platforms":["Space Segment","Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2054","stixId":"attack-pattern--b4a1b631-468e-4076-ad98-54cca318b610","name":"Data Manipulation","description":"Adversaries may insert, delete, or manipulate data in order to influence external outcomes or hide activity, thus threatening the integrity of the data. By manipulating data, adversaries may attempt to affect a business process, organizational understanding, or decision making. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2054"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2054.001","url":"https://attack.mitre.org/techniques/T2054/001"}]},{"id":"SSH.T2054.002","stixId":"attack-pattern--6bffd065-f3c9-4c7f-a617-056cc9a9e57b","name":"Transmitted Data Manipulation","description":"an attacker can modify transmitted data, jamming or overpowering the original signal and retransmitting a modified copy to the receiver, to command a spacecraft or to lead the system owner to erroneous decision. An attacker can target the telecommands sent from a GS, to change the spacecraft behavior, or he can tamper the telemetry sent from a spacecraft to change the GS received data. Intercepted and modified range measurement sent to the control center could lead to erroneous range measurements, which could cause incorrect trajectory determination. Mitigations are redundancy/diversity to protect the source and authentication to protect the message. To protect the data source, a star sensor offers ah high level of reliability. An attacker can also target the payload data sent from or to a spacecraft. To mitigate this, Navigation Message Authentication (NMA) uses symmetric/asymmetric key encryption to provide authenticity and integrity of the navigation data to the receiver.","url":"https://spaceshield.esa.int/techniques/T2054/002","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2054.002 Transmitted Data Manipulation","platforms":["Space Segment","Ground Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2054","stixId":"attack-pattern--b4a1b631-468e-4076-ad98-54cca318b610","name":"Data Manipulation","description":"Adversaries may insert, delete, or manipulate data in order to influence external outcomes or hide activity, thus threatening the integrity of the data. By manipulating data, adversaries may attempt to affect a business process, organizational understanding, or decision making. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2054"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2054.002","url":"https://spaceshield.esa.int/techniques/T2054/002"}]},{"id":"SSH.T2054.003","stixId":"attack-pattern--8c1cda8b-bba1-487e-afe4-6fc550553912","name":"Runtime Data Manipulation","description":"An attacker can use a controlled payload software or component to manipulate data of that or another component during the execution, if a MMU or a MPU is not implemented or is misconfigured. Only the most recent space qualified microprocessors (LEONII/III) have a MMU available, that provides only write protection. For secure spacecraft avionics, protection against read/write and execution access is necessary. The MMU or a MPU is extremely important if the payload is not trusted. (Citation: MITRE ATT&CK) (Citation: SRC015)","url":"https://spaceshield.esa.int/techniques/T2054/003","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2054.003 Runtime Data Manipulation","platforms":["Space Segment","Space-link communication"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2054","stixId":"attack-pattern--b4a1b631-468e-4076-ad98-54cca318b610","name":"Data Manipulation","description":"Adversaries may insert, delete, or manipulate data in order to influence external outcomes or hide activity, thus threatening the integrity of the data. By manipulating data, adversaries may attempt to affect a business process, organizational understanding, or decision making. (Citation: MITRE ATT&CK)","url":"https://spaceshield.esa.int/techniques/T2054"}],"mitigations":[{"id":"SSH.M2008","stixId":"course-of-action--feb1223f-a844-4cc8-84ed-2442a2d09f0f","name":"MMU and MPU","description":"For secure spacecraft avionics, protection against read/write and execution access is necessary. The MMU or a MPU provide it, extremely important if the payload is not trusted. (Citation: SRC015)","url":"https://spaceshield.esa.int/mitigations/M2008"}],"externalReferences":[{"source":"mitre-attack","id":"T2054.003","url":"https://spaceshield.esa.int/techniques/T2054/003"},{"source":"SRC015","url":"https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=5226855"},{"source":"MITRE ATT&CK","url":"https://attack.mitre.org"}]},{"id":"SSH.T2055","stixId":"attack-pattern--fb7b39b6-5e3c-4327-ae4a-e0a3bdfb6b7c","name":"Loss of spacecraft telecommanding","description":"an attacker can interrupt the communication link between a ground station and a spacecraft by changing the TC channel configuration.","url":"https://spaceshield.esa.int/techniques/T2055","model":"SPACE-SHIELD","matrix":"SSH","type":"technique","label":"[SSH] SSH.T2055 Loss of spacecraft telecommanding","platforms":["Space-link communication","Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2055","url":"https://spaceshield.esa.int/techniques/T2055"}]},{"id":"SSH.T2055.001","stixId":"attack-pattern--47370fa0-7d75-4acc-bcb9-29a52ba1a625","name":"Replacement of authentication keys","description":"An attacker can replace the authentication keys (e.g SDLS session keys) to disconnect the legitimate ground station and potentially hijack the connection.","url":"https://spaceshield.esa.int/techniques/T2055/001","model":"SPACE-SHIELD","matrix":"SSH","type":"subtechnique","label":"[SSH] SSH.T2055.001 Replacement of authentication keys","platforms":["Space-link communication","Space Segment","Ground Segment"],"tactics":[{"id":"SSH.TA0040","name":"Impact","shortname":"impact"}],"parentTechniques":[{"id":"SSH.T2055","stixId":"attack-pattern--fb7b39b6-5e3c-4327-ae4a-e0a3bdfb6b7c","name":"Loss of spacecraft telecommanding","description":"an attacker can interrupt the communication link between a ground station and a spacecraft by changing the TC channel configuration.","url":"https://spaceshield.esa.int/techniques/T2055"}],"mitigations":[],"externalReferences":[{"source":"mitre-attack","id":"T2055.001","url":"https://spaceshield.esa.int/techniques/T2055/001"}]}]};

